//! Bilibili QR login and private yt-dlp cookie snapshots.
use anyhow::{Context, Result, bail, ensure};
use serde_json::Value;
use std::{
    collections::BTreeMap,
    io::Write,
    path::{Path, PathBuf},
    time::{Duration, Instant},
};

const PASSPORT: &str = "https://passport.bilibili.com/x/passport-login/web/qrcode";
const USER_AGENT: &str = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36";
const COOKIE_NAMES: &[&str] = &[
    "SESSDATA",
    "bili_jct",
    "DedeUserID",
    "DedeUserID__ckMd5",
    "buvid3",
    "buvid4",
    "b_nut",
];
type Cookies = BTreeMap<String, String>;

pub const BILIBILI_SETUP_TIP: &str = "使用 Bilibili 视频时，推荐先运行 course2md --login bilibili 扫码登录，可下载账号权限范围内更高清晰度的视频。 / For Bilibili videos, run course2md --login bilibili first to scan a QR code; downloads can then use higher resolutions available to your account.";

/// Keep the original failure visible; login is a suggested next step, not a diagnosis.
pub fn with_bilibili_login_tip(url: &str, error: anyhow::Error) -> anyhow::Error {
    let message = format!("{error:#}");
    if is_bilibili_url(url) && !message.contains("--login bilibili") {
        anyhow::anyhow!(
            "{message}\n提示：可运行 course2md --login bilibili 扫码登录后重试；已登录时可重新登录。 / Hint: run course2md --login bilibili and scan the QR code to retry; if already logged in, log in again."
        )
    } else {
        error
    }
}

pub fn cookie_path() -> PathBuf {
    crate::config::config_dir().join("auth/bilibili.cookies.txt")
}

pub fn is_bilibili_url(input: &str) -> bool {
    let parsed = url::Url::parse(input).or_else(|_| url::Url::parse(&format!("https://{input}")));
    parsed.is_ok_and(|url| {
        matches!(url.scheme(), "http" | "https")
            && url.host_str().is_some_and(|host| {
                host == "bilibili.com" || host.ends_with(".bilibili.com") || host == "b23.tv"
            })
    })
}

/// yt-dlp rewrites cookie files on exit. Give each subprocess a private snapshot
/// so simultaneous preview/subtitle/download requests cannot corrupt saved login.
/// The caller must keep the returned file alive until the subprocess exits.
pub fn configure_ytdlp(
    command: &mut std::process::Command,
    url: &str,
) -> Result<Option<tempfile::NamedTempFile>> {
    configure_with_path(command, url, &cookie_path())
}

fn configure_with_path(
    command: &mut std::process::Command,
    url: &str,
    path: &Path,
) -> Result<Option<tempfile::NamedTempFile>> {
    if !is_bilibili_url(url) {
        return Ok(None);
    }
    let bytes = match std::fs::read(path) {
        Ok(bytes) => bytes,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(e) => {
            return Err(e)
                .context("无法读取 Bilibili 登录状态，请重新运行 course2md --login bilibili / Cannot read Bilibili login state; run course2md --login bilibili again");
        }
    };
    let mut file = tempfile::NamedTempFile::new()?;
    file.write_all(&bytes)?;
    file.flush()?;
    command.arg("--cookies").arg(file.path());
    Ok(Some(file))
}

/// Remove the saved session. `verbose` additionally prints the CLI outcome.
fn remove_bilibili_login(verbose: bool) -> Result<()> {
    match std::fs::remove_file(cookie_path()) {
        Ok(()) => {
            if verbose {
                println!("已清除 Bilibili 本地登录状态。/ Bilibili login removed.");
            }
            Ok(())
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            if verbose {
                println!("尚未登录 Bilibili。/ No Bilibili login saved.");
            }
            Ok(())
        }
        Err(e) => Err(e).context("清除 Bilibili 登录状态失败 / Could not remove Bilibili login"),
    }
}

/// Remove the saved session without CLI output.
pub fn clear_bilibili_login() -> Result<()> {
    remove_bilibili_login(false)
}

pub fn logout_bilibili() -> Result<()> {
    remove_bilibili_login(true)
}

fn insert_cookie(cookies: &mut Cookies, name: &str, value: &str) {
    if COOKIE_NAMES.contains(&name)
        && !value.is_empty()
        && !value.chars().any(|c| c.is_control() || c == ';')
    {
        cookies.insert(name.into(), value.into());
    }
}

fn read_cookies(response: &ureq::Response, cookies: &mut Cookies) {
    for header in response.all("set-cookie") {
        if let Some((name, value)) = header
            .split(';')
            .next()
            .and_then(|pair| pair.split_once('='))
        {
            insert_cookie(cookies, name.trim(), value.trim());
        }
    }
}

fn complete(cookies: &Cookies) -> bool {
    ["SESSDATA", "bili_jct", "DedeUserID"]
        .iter()
        .all(|key| cookies.contains_key(*key))
}

fn cookie_header(cookies: &Cookies) -> String {
    cookies
        .iter()
        .map(|(k, v)| format!("{k}={v}"))
        .collect::<Vec<_>>()
        .join("; ")
}

fn netscape(cookies: &Cookies) -> Result<String> {
    ensure!(complete(cookies), "登录响应未包含完整凭据，请重新扫码 / Login response did not include complete credentials; scan the QR code again");
    let mut text = String::from(
        "# Netscape HTTP Cookie File\n# course2md Bilibili login; do not share this file.\n",
    );
    for (name, value) in cookies {
        // Session cookies (expiry 0) remain valid until the server expires them.
        text.push_str(&format!(
            ".bilibili.com\tTRUE\t/\tTRUE\t0\t{name}\t{value}\n"
        ));
    }
    Ok(text)
}

fn save_cookies(path: &Path, cookies: &Cookies) -> Result<()> {
    let text = netscape(cookies)?;
    let parent = path.parent().context("登录状态路径无效 / Invalid login state path")?;
    std::fs::create_dir_all(parent)?;
    let mut file = tempfile::NamedTempFile::new_in(parent)?; // mode 0600 on Unix
    file.write_all(text.as_bytes())?;
    file.as_file().sync_all()?;
    file.persist(path)
        .map_err(|e| e.error)
        .context("保存 Bilibili 登录状态失败 / Failed to save Bilibili login state")?;
    Ok(())
}

fn request(agent: &ureq::Agent, url: &str, cookies: &Cookies) -> Result<ureq::Response> {
    // Transport errors may contain the URL, including a one-use QR ticket.
    agent
        .get(url)
        .set("User-Agent", USER_AGENT)
        .set("Referer", "https://passport.bilibili.com/")
        .set("Cookie", &cookie_header(cookies))
        .call()
        .map_err(|_| anyhow::anyhow!("Bilibili 登录请求失败，请检查网络后重试 / Bilibili login request failed; check the network and retry"))
}

fn data(response: ureq::Response) -> Result<Value> {
    let value: Value = response.into_json().context("无法解析 Bilibili 登录响应 / Cannot parse Bilibili login response")?;
    ensure!(
        value["code"].as_i64() == Some(0),
        "Bilibili 登录接口返回错误 / Bilibili login API returned an error"
    );
    ensure!(value["data"].is_object(), "Bilibili 登录响应缺少 data / Bilibili login response is missing data");
    Ok(value["data"].clone())
}

fn trusted_ticket_url(raw: &str) -> Result<url::Url> {
    let url = url::Url::parse(raw).map_err(|_| anyhow::anyhow!("Bilibili 登录跳转地址无效 / Invalid Bilibili login redirect URL"))?;
    ensure!(
        url.scheme() == "https"
            && url.username().is_empty()
            && url.password().is_none()
            && url.port_or_known_default() == Some(443)
            && url
                .host_str()
                .is_some_and(|host| host == "bilibili.com" || host.ends_with(".bilibili.com")),
        "Bilibili 登录跳转地址不受支持 / Unsupported Bilibili login redirect URL"
    );
    Ok(url)
}

fn finish_login(
    agent: &ureq::Agent,
    login: &Value,
    cookies: &mut Cookies,
) -> Result<AccountProfile> {
    finish_with(login, cookies, |url, cookies| request(agent, url, cookies))
}

fn finish_with(
    login: &Value,
    cookies: &mut Cookies,
    mut fetch: impl FnMut(&str, &Cookies) -> Result<ureq::Response>,
) -> Result<AccountProfile> {
    if let Some(raw) = login["url"].as_str().filter(|s| !s.is_empty()) {
        // Older responses embed cookies in the callback query; newer responses
        // provide a crossDomain ticket whose response sets the real cookies.
        let url = url::Url::parse(raw).map_err(|_| anyhow::anyhow!("登录回调地址无效 / Invalid login callback URL"))?;
        for pair in url.query().unwrap_or_default().split('&') {
            if let Some((name, value)) = pair.split_once('=')
                && !cookies.contains_key(name)
            {
                insert_cookie(cookies, name, value);
            }
        }
        if !complete(cookies) {
            let mut next = trusted_ticket_url(raw)?;
            for _ in 0..5 {
                let response = fetch(next.as_str(), cookies)?;
                read_cookies(&response, cookies);
                if complete(cookies) {
                    break;
                }
                if !(300..400).contains(&response.status()) {
                    break;
                }
                let location = response.header("location").context("登录跳转缺少地址 / Login redirect is missing an address")?;
                let joined = next
                    .join(location)
                    .map_err(|_| anyhow::anyhow!("登录跳转地址无效 / Invalid login redirect URL"))?;
                next = trusted_ticket_url(joined.as_str())?;
            }
        }
    }
    ensure!(
        complete(cookies),
        "登录响应缺少凭据，请重新运行 course2md --login bilibili / Login response is missing credentials; run course2md --login bilibili again"
    );
    let profile = data(fetch(
        "https://api.bilibili.com/x/web-interface/nav",
        cookies,
    )?)?;
    ensure!(
        profile["isLogin"].as_bool() == Some(true),
        "Bilibili 未确认登录，请重新扫码 / Bilibili did not confirm the login; scan the QR code again"
    );
    Ok(AccountProfile {
        name: profile["uname"]
            .as_str()
            .unwrap_or("Bilibili 用户")
            .to_owned(),
    })
}

#[derive(Debug, PartialEq)]
enum QrState {
    Waiting,
    Confirm,
    Expired,
    Done,
}
fn qr_state(value: &Value) -> Result<QrState> {
    match value["code"].as_i64() {
        Some(86101) => Ok(QrState::Waiting),
        Some(86090) => Ok(QrState::Confirm),
        Some(86038) => Ok(QrState::Expired),
        Some(0) => Ok(QrState::Done),
        _ => bail!("Bilibili 返回未知扫码状态，请重试 / Bilibili returned an unknown QR scan status; retry"),
    }
}

/// Verified public account information. Credentials are never exposed or Debug-printed.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AccountProfile {
    pub name: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum AccountStatus {
    Disconnected,
    Connected(AccountProfile),
    Expired,
}

fn login_agent() -> ureq::Agent {
    crate::runtime::http_agent(Duration::from_secs(12))
}

/// Check saved credentials against Bilibili. A network failure is an error, not logout.
pub fn bilibili_account_status() -> Result<AccountStatus> {
    let text = match std::fs::read_to_string(cookie_path()) {
        Ok(text) => text,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            return Ok(AccountStatus::Disconnected);
        }
        Err(_) => bail!("无法读取本地登录状态，请重新登录 / Cannot read the saved login state; log in again"),
    };
    let mut cookies = Cookies::new();
    for line in text.lines().filter(|line| !line.starts_with('#')) {
        let columns: Vec<_> = line.split('\t').collect();
        if columns.len() == 7 && columns[0] == ".bilibili.com" {
            insert_cookie(&mut cookies, columns[5], columns[6]);
        }
    }
    if !complete(&cookies) {
        return Ok(AccountStatus::Expired);
    }
    let response = request(
        &login_agent(),
        "https://api.bilibili.com/x/web-interface/nav",
        &cookies,
    )?;
    let value: Value = response
        .into_json()
        .map_err(|_| anyhow::anyhow!("无法解析账号状态 / Cannot parse account status"))?;
    if value["code"].as_i64() == Some(-101) {
        return Ok(AccountStatus::Expired);
    }
    ensure!(
        value["code"].as_i64() == Some(0),
        "无法验证账号状态，请稍后重试 / Cannot verify account status; retry later"
    );
    let profile = &value["data"];
    match profile["isLogin"].as_bool() {
        Some(true) => {}
        Some(false) => return Ok(AccountStatus::Expired),
        None => bail!("账号状态响应不完整，请稍后重试 / Account status response is incomplete; retry later"),
    }
    Ok(AccountStatus::Connected(AccountProfile {
        name: profile["uname"]
            .as_str()
            .unwrap_or("Bilibili 用户")
            .to_owned(),
    }))
}

/// A successful poll returns credentials in memory. The caller explicitly commits
/// only after checking that its GUI session is still current.
pub struct VerifiedLogin {
    cookies: Cookies,
    pub profile: AccountProfile,
}
impl VerifiedLogin {
    pub fn save(self) -> Result<AccountProfile> {
        save_cookies(&cookie_path(), &self.cookies)?;
        Ok(self.profile)
    }
}

pub enum QrPoll {
    Waiting,
    AwaitingConfirmation,
    Expired,
    Authenticated(VerifiedLogin),
}

/// Blocking, reusable session API. Run generation and polling off the UI thread.
/// Intentionally does not implement Debug: it owns one-use login tickets.
pub struct QrSession {
    agent: ureq::Agent,
    cookies: Cookies,
    poll_url: url::Url,
    code: qrcode::QrCode,
    started: Instant,
}
impl QrSession {
    pub fn generate() -> Result<Self> {
        let agent = login_agent();
        let mut cookies = Cookies::new();
        let response = request(&agent, &format!("{PASSPORT}/generate"), &cookies)?;
        read_cookies(&response, &mut cookies);
        let qr = data(response)?;
        let key = qr["qrcode_key"].as_str().context("二维码响应缺少 key / QR code response is missing key")?;
        let link = qr["url"].as_str().context("二维码响应缺少 url / QR code response is missing url")?;
        let code = qrcode::QrCode::new(link.as_bytes()).context("生成二维码失败 / Failed to generate QR code")?;
        let mut poll_url = url::Url::parse(&format!("{PASSPORT}/poll"))?;
        poll_url.query_pairs_mut().append_pair("qrcode_key", key);
        Ok(Self {
            agent,
            cookies,
            poll_url,
            code,
            started: Instant::now(),
        })
    }

    /// Renderable QR modules only; callers must add a four-module white quiet zone.
    pub fn modules(&self) -> Vec<Vec<bool>> {
        (0..self.code.width())
            .map(|y| {
                (0..self.code.width())
                    .map(|x| self.code[(x, y)] == qrcode::Color::Dark)
                    .collect()
            })
            .collect()
    }

    pub fn remaining(&self) -> Duration {
        Duration::from_secs(180).saturating_sub(self.started.elapsed())
    }

    pub fn poll(&mut self) -> Result<QrPoll> {
        if self.remaining().is_zero() {
            return Ok(QrPoll::Expired);
        }
        let response = request(&self.agent, self.poll_url.as_str(), &self.cookies)?;
        read_cookies(&response, &mut self.cookies);
        let login = data(response)?;
        match qr_state(&login)? {
            QrState::Waiting => Ok(QrPoll::Waiting),
            QrState::Confirm => Ok(QrPoll::AwaitingConfirmation),
            QrState::Expired => Ok(QrPoll::Expired),
            QrState::Done => {
                let profile = finish_login(&self.agent, &login, &mut self.cookies)?;
                Ok(QrPoll::Authenticated(VerifiedLogin {
                    cookies: std::mem::take(&mut self.cookies),
                    profile,
                }))
            }
        }
    }
}

pub fn login_bilibili() -> Result<()> {
    let mut session = QrSession::generate()?;
    println!("请用哔哩哔哩 App 扫描二维码，并在手机上确认登录（Ctrl+C 取消）：/ Scan with the Bilibili app and confirm the login on your phone (Ctrl+C to cancel):");
    println!(
        "{}",
        session
            .code
            .render::<qrcode::render::unicode::Dense1x2>()
            .dark_color(qrcode::render::unicode::Dense1x2::Light)
            .light_color(qrcode::render::unicode::Dense1x2::Dark)
            .build()
    );
    let mut confirmed = false;
    loop {
        std::thread::sleep(Duration::from_secs(2));
        match session.poll()? {
            QrPoll::Waiting => {}
            QrPoll::AwaitingConfirmation => {
                if !confirmed {
                    println!("已扫码，请在手机上确认登录。/ Code scanned; confirm the login on your phone.");
                    confirmed = true;
                }
            }
            QrPoll::Expired => bail!(
                "二维码已过期，请重新运行 course2md --login bilibili / QR code expired; run course2md --login bilibili again"
            ),
            QrPoll::Authenticated(login) => {
                login.save()?;
                println!("Bilibili 登录成功。预览、字幕和视频下载将自动使用此登录状态。/ Bilibili login successful. Previews, subtitles and video downloads will use it automatically.");
                return Ok(());
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn login_tip_preserves_failure_and_only_applies_to_bilibili_once() {
        let error = anyhow::anyhow!("HTTP Error 403").context("无法读取视频");
        let error = with_bilibili_login_tip("https://b23.tv/example", error);
        let error = with_bilibili_login_tip("https://b23.tv/example", error);
        let message = error.to_string();
        assert!(message.contains("无法读取视频: HTTP Error 403"));
        assert_eq!(message.matches("--login bilibili").count(), 2);
        let error = with_bilibili_login_tip(
            "https://youtube.com/watch?v=bilibili.com",
            anyhow::anyhow!("HTTP Error 403"),
        );
        assert_eq!(error.to_string(), "HTTP Error 403");
    }

    #[test]
    fn cookie_scope_excludes_lookalike_hosts() {
        for url in [
            "https://www.bilibili.com/video/BV1",
            "https://b23.tv/test",
            "www.bilibili.com/video/BV1",
        ] {
            assert!(is_bilibili_url(url));
        }
        for url in [
            "https://youtube.com/?bilibili.com",
            "https://bilibili.com.evil.test",
            "https://bilibili.com@evil.test",
            "file:///bilibili.com",
        ] {
            assert!(!is_bilibili_url(url));
        }
    }
    #[test]
    fn qr_states_are_explicit() {
        for (code, state) in [
            (86101, QrState::Waiting),
            (86090, QrState::Confirm),
            (86038, QrState::Expired),
            (0, QrState::Done),
        ] {
            assert_eq!(qr_state(&serde_json::json!({"code":code})).unwrap(), state);
        }
        assert!(qr_state(&serde_json::json!({})).is_err());
        assert!(qr_state(&serde_json::json!({"code":-1})).is_err());
    }
    #[test]
    fn cookies_are_private_complete_and_in_netscape_format() {
        let mut cookies = Cookies::new();
        let response: ureq::Response = "HTTP/1.1 200 OK\r\nSet-Cookie: SESSDATA=abc%2C123; Domain=.bilibili.com; HttpOnly; Secure\r\nSet-Cookie: bili_jct=csrf; Path=/\r\nSet-Cookie: DedeUserID=123; Path=/\r\n\r\n".parse().unwrap();
        read_cookies(&response, &mut cookies);
        insert_cookie(&mut cookies, "evil", "ignored");
        insert_cookie(&mut cookies, "buvid3", "bad\ninjection");
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("cookies.txt");
        save_cookies(&path, &cookies).unwrap();
        let text = std::fs::read_to_string(&path).unwrap();
        assert!(text.contains(".bilibili.com\tTRUE\t/\tTRUE\t0\tSESSDATA\tabc%2C123\n"));
        assert!(!text.contains("evil"));
        assert!(!text.contains("injection"));
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            assert_eq!(
                std::fs::metadata(&path).unwrap().permissions().mode() & 0o777,
                0o600
            );
        }
        assert!(save_cookies(&path, &Cookies::new()).is_err());
        assert_eq!(std::fs::read_to_string(path).unwrap(), text);
    }
    #[test]
    fn legacy_and_crossdomain_login_validate_before_saving() {
        for callback in [
            "https://passport.biligame.com/crossDomain?SESSDATA=abc%2C123&bili_jct=csrf&DedeUserID=123",
            "https://passport.bilibili.com/x/passport-login/web/crossDomain?ticket=one-use",
        ] {
            let mut cookies = Cookies::new();
            let mut calls = Vec::new();
            finish_with(&serde_json::json!({"url":callback}), &mut cookies, |url, jar| {
                calls.push(url.to_owned());
                if url.contains("/nav") {
                    assert!(complete(jar));
                    assert_eq!(jar["SESSDATA"], "abc%2C123");
                    Ok(ureq::Response::new(200, "OK", r#"{"code":0,"data":{"isLogin":true}}"#).unwrap())
                } else {
                    Ok("HTTP/1.1 302 Found\r\nSet-Cookie: SESSDATA=abc%2C123; Secure\r\nSet-Cookie: bili_jct=csrf\r\nSet-Cookie: DedeUserID=123\r\nLocation: https://www.bilibili.com/\r\n\r\n".parse().unwrap())
                }
            }).unwrap();
            assert_eq!(
                calls.last().unwrap(),
                "https://api.bilibili.com/x/web-interface/nav"
            );
            assert_eq!(
                calls.len(),
                if callback.contains("ticket=") { 2 } else { 1 }
            );
            assert!(
                finish_with(&serde_json::json!({}), &mut cookies, |_, _| {
                    Ok(
                        ureq::Response::new(200, "OK", r#"{"code":0,"data":{"isLogin":false}}"#)
                            .unwrap(),
                    )
                })
                .is_err()
            );
        }
    }

    #[test]
    fn downloader_snapshots_do_not_modify_saved_login() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("saved.txt");
        std::fs::write(&path, "saved session").unwrap();
        let mut first = std::process::Command::new("yt-dlp");
        let mut second = std::process::Command::new("yt-dlp");
        let a = configure_with_path(&mut first, "https://www.bilibili.com/video/BV1", &path)
            .unwrap()
            .unwrap();
        let b = configure_with_path(&mut second, "https://b23.tv/test", &path)
            .unwrap()
            .unwrap();
        assert_ne!(a.path(), b.path());
        std::fs::write(a.path(), "rewritten by yt-dlp").unwrap();
        assert_eq!(std::fs::read_to_string(&path).unwrap(), "saved session");
        assert_eq!(std::fs::read_to_string(b.path()).unwrap(), "saved session");
        let mut other = std::process::Command::new("yt-dlp");
        assert!(
            configure_with_path(&mut other, "https://youtube.com/", &path)
                .unwrap()
                .is_none()
        );
        assert_eq!(other.get_args().count(), 0);
        assert!(
            configure_with_path(
                &mut other,
                "https://b23.tv/test",
                &dir.path().join("missing")
            )
            .unwrap()
            .is_none()
        );
    }

    #[test]
    #[ignore = "requires Bilibili network access; generates a QR session without logging in"]
    fn live_qr_generation_and_waiting_state() {
        let mut session = QrSession::generate().unwrap();
        let modules = session.modules();
        assert!(!modules.is_empty());
        assert!(modules.iter().all(|row| row.len() == modules.len()));
        assert!(matches!(session.poll().unwrap(), QrPoll::Waiting));
        // Local deadline terminates without a further network request.
        session.started = Instant::now() - Duration::from_secs(181);
        assert!(matches!(session.poll().unwrap(), QrPoll::Expired));
    }

    #[test]
    fn ticket_redirects_cannot_leave_bilibili() {
        assert!(
            trusted_ticket_url(
                "https://passport.bilibili.com/x/passport-login/web/crossDomain?ticket=test"
            )
            .is_ok()
        );
        for url in [
            "http://passport.bilibili.com/",
            "https://bilibili.com.evil.test/",
            "https://evil.test/",
            "https://user@bilibili.com/",
        ] {
            assert!(trusted_ticket_url(url).is_err());
        }
    }
}

//! Secret storage is deliberately separate from serializable preferences and task records.
//!
//! Tests inject `MemoryCredentialVault`; they never access the user's Keychain.

use anyhow::{Result, anyhow, bail};
#[cfg(any(test, not(target_os = "macos")))]
use std::collections::BTreeMap;
use std::fmt;
#[cfg(not(target_os = "macos"))]
use std::path::Path;
use std::path::PathBuf;
use std::sync::Arc;
#[cfg(any(test, not(target_os = "macos")))]
use std::sync::Mutex;
use zeroize::Zeroizing;

pub type CredentialRef = String;

/// A secret cannot accidentally be serialized or printed by a derived Debug implementation.
pub struct Secret(Zeroizing<String>);

impl Secret {
    pub fn new(value: impl Into<String>) -> Self {
        Self(Zeroizing::new(value.into()))
    }

    pub fn expose(&self) -> &str {
        self.0.as_str()
    }

    pub fn is_empty(&self) -> bool {
        self.expose().trim().is_empty()
    }
}

impl fmt::Debug for Secret {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("Secret([REDACTED])")
    }
}

/// Insert always creates a new immutable identity. Updating a service cannot change the
/// credential used by an already queued task. Resolving never consults mutable environment
/// variables; a user-selected environment credential must be captured at publication time.
pub trait CredentialVault: Send + Sync {
    fn insert(&self, secret: Secret) -> Result<CredentialRef>;
    fn resolve(&self, reference: &str) -> Result<Secret>;
    fn remove(&self, reference: &str) -> Result<()>;
}

fn new_reference() -> String {
    format!("credential-{}", uuid::Uuid::new_v4())
}

fn validate_reference(reference: &str) -> Result<()> {
    let id = reference.strip_prefix("credential-").unwrap_or("");
    if uuid::Uuid::parse_str(id).is_err() {
        bail!("凭据引用无效，请为此服务重新保存 API Key");
    }
    Ok(())
}

/// In-memory isolated store for tests and caller-controlled temporary use.
/// It intentionally does not provide a plaintext file fallback.
#[cfg(test)]
#[derive(Default)]
pub struct MemoryCredentialVault {
    values: Mutex<BTreeMap<CredentialRef, Zeroizing<String>>>,
}

#[cfg(test)]
impl MemoryCredentialVault {
    pub fn new() -> Self {
        Self::default()
    }
}

#[cfg(test)]
impl CredentialVault for MemoryCredentialVault {
    fn insert(&self, secret: Secret) -> Result<CredentialRef> {
        if secret.is_empty() {
            bail!("请输入 API Key");
        }
        let reference = new_reference();
        self.values
            .lock()
            .map_err(|_| anyhow!("暂时无法保存凭据"))?
            .insert(
                reference.clone(),
                Zeroizing::new(secret.expose().to_owned()),
            );
        Ok(reference)
    }

    fn resolve(&self, reference: &str) -> Result<Secret> {
        validate_reference(reference)?;
        self.values
            .lock()
            .map_err(|_| anyhow!("暂时无法读取凭据"))?
            .get(reference)
            .map(|value| Secret::new(value.as_str()))
            .ok_or_else(|| anyhow!("找不到此服务的凭据，请重新保存 API Key"))
    }

    fn remove(&self, reference: &str) -> Result<()> {
        validate_reference(reference)?;
        self.values
            .lock()
            .map_err(|_| anyhow!("暂时无法移除凭据"))?
            .remove(reference);
        Ok(())
    }
}

#[cfg(target_os = "macos")]
pub struct KeychainCredentialVault {
    service: String,
}

#[cfg(target_os = "macos")]
impl Default for KeychainCredentialVault {
    fn default() -> Self {
        Self {
            service: "com.course2md.desktop.service-credentials.v1".into(),
        }
    }
}

#[cfg(target_os = "macos")]
impl CredentialVault for KeychainCredentialVault {
    fn insert(&self, secret: Secret) -> Result<CredentialRef> {
        if secret.is_empty() {
            bail!("请输入 API Key");
        }
        let reference = new_reference();
        security_framework::passwords::set_generic_password(
            &self.service,
            &reference,
            secret.expose().as_bytes(),
        )
        .map_err(|error| anyhow!("无法将 API Key 保存到钥匙串（系统代码 {}）", error.code()))?;
        Ok(reference)
    }

    fn resolve(&self, reference: &str) -> Result<Secret> {
        validate_reference(reference)?;
        let bytes = security_framework::passwords::get_generic_password(&self.service, reference)
            .map_err(|error| match error.code() {
            -25300 => anyhow!("钥匙串中找不到此服务的凭据，请重新保存 API Key"),
            code => anyhow!("暂时无法读取此服务的钥匙串凭据（系统代码 {code}）"),
        })?;
        // Keep the intermediate byte buffer zeroizing as well as the returned UTF-8 value.
        let bytes = Zeroizing::new(bytes);
        let value = std::str::from_utf8(&bytes)
            .map_err(|_| anyhow!("此服务的凭据无法读取，请重新保存 API Key"))?;
        Ok(Secret::new(value))
    }

    fn remove(&self, reference: &str) -> Result<()> {
        validate_reference(reference)?;
        match security_framework::passwords::delete_generic_password(&self.service, reference) {
            Ok(()) => Ok(()),
            Err(error) if error.code() == -25300 => Ok(()),
            Err(error) => bail!("无法移除此服务的钥匙串凭据（系统代码 {}）", error.code()),
        }
    }
}

/// System keyring-backed credential store for Linux (Secret Service) and
/// Windows (Credential Manager). Availability is checked once through the
/// keyring crate's store status; when no system keyring is reachable the
/// caller falls back to `FileCredentialVault`.
#[cfg(not(target_os = "macos"))]
pub struct KeyringCredentialVault {
    service: String,
}

#[cfg(not(target_os = "macos"))]
impl KeyringCredentialVault {
    pub fn new() -> Self {
        Self {
            service: "com.course2md.desktop.service-credentials.v1".into(),
        }
    }

    /// Whether the platform credential store initialized successfully.
    pub fn available() -> bool {
        keyring::Entry::store_status().is_ok()
    }
}

#[cfg(not(target_os = "macos"))]
impl CredentialVault for KeyringCredentialVault {
    fn insert(&self, secret: Secret) -> Result<CredentialRef> {
        if secret.is_empty() {
            bail!("请输入 API Key");
        }
        let reference = new_reference();
        let entry = keyring::Entry::new(&self.service, &reference)?;
        entry.set_password(secret.expose())?;
        Ok(reference)
    }

    fn resolve(&self, reference: &str) -> Result<Secret> {
        validate_reference(reference)?;
        let entry = keyring::Entry::new(&self.service, reference)?;
        let password = entry.get_password()?;
        Ok(Secret::new(password))
    }

    fn remove(&self, reference: &str) -> Result<()> {
        validate_reference(reference)?;
        let entry = keyring::Entry::new(&self.service, reference)?;
        // 与 Keychain 实现一致：条目不存在视为已删除
        match entry.delete_credential() {
            Ok(()) | Err(keyring::Error::NoEntry) => Ok(()),
            Err(error) => Err(error.into()),
        }
    }
}

/// File-backed fallback for platforms without a reachable system keychain.
///
/// Credentials are written as JSON next to the desktop preferences. The file is
/// created through `atomic_write`, which uses a 0o600 temporary file on Unix, so
/// the persisted secrets are not world-readable. This mirrors the CLI, which
/// stores API keys in the user's `config.toml` under the same permissions.
#[cfg(not(target_os = "macos"))]
pub struct FileCredentialVault {
    path: PathBuf,
    values: Mutex<BTreeMap<CredentialRef, Zeroizing<String>>>,
    /// 文件损坏/不可读时的错误：存在期间拒绝任何写入，避免用空表覆盖原文件丢密钥
    load_error: Mutex<Option<String>>,
}

#[cfg(not(target_os = "macos"))]
impl FileCredentialVault {
    pub fn new(path: impl Into<PathBuf>) -> Self {
        let path = path.into();
        let (values, load_error) = match Self::load(&path) {
            Ok(values) => (values, None),
            Err(error) => {
                // 写入锁定说明见 refuse_if_unreadable；不引入日志框架，错误在写入尝试时展示
                (BTreeMap::new(), Some(format!("{error:#}")))
            }
        };
        Self {
            path,
            values: Mutex::new(values),
            load_error: Mutex::new(load_error),
        }
    }

    fn refuse_if_unreadable(&self) -> Result<()> {
        if let Some(error) = self.load_error.lock().map_err(|_| anyhow!("暂时无法访问凭据"))?.as_ref() {
            bail!(
                "凭据文件无法读取（{}），为避免覆盖丢失已暂停写入；请修复或备份后删除该文件重试：{}",
                error,
                self.path.display()
            );
        }
        Ok(())
    }

    fn load(path: &Path) -> Result<BTreeMap<CredentialRef, Zeroizing<String>>> {
        let bytes = match std::fs::read(path) {
            Ok(bytes) => bytes,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return Ok(BTreeMap::new());
            }
            Err(error) => return Err(error.into()),
        };
        let plain: BTreeMap<CredentialRef, String> = serde_json::from_slice(&bytes)?;
        Ok(plain
            .into_iter()
            .map(|(reference, value)| (reference, Zeroizing::new(value)))
            .collect())
    }

    fn persist(&self, values: &BTreeMap<CredentialRef, Zeroizing<String>>) -> Result<()> {
        let plain: BTreeMap<CredentialRef, String> = values
            .iter()
            .map(|(reference, value)| (reference.clone(), value.as_str().to_owned()))
            .collect();
        let bytes = serde_json::to_vec_pretty(&plain)?;
        course2md::checkpoint::atomic_write(&self.path, &bytes)
    }
}

#[cfg(not(target_os = "macos"))]
impl CredentialVault for FileCredentialVault {
    fn insert(&self, secret: Secret) -> Result<CredentialRef> {
        if secret.is_empty() {
            bail!("请输入 API Key");
        }
        self.refuse_if_unreadable()?;
        let reference = new_reference();
        let mut values = self
            .values
            .lock()
            .map_err(|_| anyhow!("暂时无法保存凭据"))?;
        values.insert(
            reference.clone(),
            Zeroizing::new(secret.expose().to_owned()),
        );
        if let Err(error) = self.persist(&values) {
            values.remove(&reference);
            return Err(error);
        }
        Ok(reference)
    }

    fn resolve(&self, reference: &str) -> Result<Secret> {
        validate_reference(reference)?;
        self.values
            .lock()
            .map_err(|_| anyhow!("暂时无法读取凭据"))?
            .get(reference)
            .map(|value| Secret::new(value.as_str()))
            .ok_or_else(|| anyhow!("找不到此服务的凭据，请重新保存 API Key"))
    }

    fn remove(&self, reference: &str) -> Result<()> {
        validate_reference(reference)?;
        self.refuse_if_unreadable()?;
        let mut values = self
            .values
            .lock()
            .map_err(|_| anyhow!("暂时无法移除凭据"))?;
        let removed = values.remove(reference);
        if let Err(error) = self.persist(&values) {
            if let Some(value) = removed {
                values.insert(reference.to_owned(), value);
            }
            return Err(error);
        }
        Ok(())
    }
}

pub fn system_vault(path: impl Into<PathBuf>) -> Arc<dyn CredentialVault> {
    #[cfg(target_os = "macos")]
    {
        let _ = path;
        Arc::new(KeychainCredentialVault::default())
    }
    #[cfg(not(target_os = "macos"))]
    {
        if KeyringCredentialVault::available() {
            Arc::new(KeyringCredentialVault::new())
        } else {
            Arc::new(FileCredentialVault::new(path))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn credential_rotation_keeps_old_task_reference_immutable() {
        let vault = MemoryCredentialVault::new();
        let original = vault.insert(Secret::new("test-only-old-key")).unwrap();
        let replacement = vault.insert(Secret::new("test-only-new-key")).unwrap();
        assert_ne!(original, replacement);
        assert_eq!(
            vault.resolve(&original).unwrap().expose(),
            "test-only-old-key"
        );
        assert_eq!(
            vault.resolve(&replacement).unwrap().expose(),
            "test-only-new-key"
        );
        vault.remove(&replacement).unwrap();
        assert!(vault.resolve(&replacement).is_err());
        assert!(vault.resolve(&original).is_ok());
    }

    #[test]
    fn debug_and_errors_cannot_expose_secret() {
        let secret = Secret::new("test-only-do-not-print");
        assert_eq!(format!("{secret:?}"), "Secret([REDACTED])");
        let vault = MemoryCredentialVault::new();
        let error = vault.resolve("test-only-do-not-print").unwrap_err();
        assert!(!error.to_string().contains("test-only-do-not-print"));
        assert!(vault.insert(Secret::new("   ")).is_err());
    }

    #[cfg(not(target_os = "macos"))]
    #[test]
    fn file_vault_persists_credentials_across_instances() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("desktop-credentials.json");
        let reference = {
            let vault = FileCredentialVault::new(&path);
            let reference = vault.insert(Secret::new("test-only-file-key")).unwrap();
            assert_eq!(
                vault.resolve(&reference).unwrap().expose(),
                "test-only-file-key"
            );
            reference
        };
        // A fresh instance reads the same credential back from disk.
        let reopened = FileCredentialVault::new(&path);
        assert_eq!(
            reopened.resolve(&reference).unwrap().expose(),
            "test-only-file-key"
        );
        reopened.remove(&reference).unwrap();
        assert!(reopened.resolve(&reference).is_err());
        // Removal is also persisted.
        let after_remove = FileCredentialVault::new(&path);
        assert!(after_remove.resolve(&reference).is_err());
    }

    #[cfg(not(target_os = "macos"))]
    #[test]
    fn file_vault_starts_empty_when_file_is_missing_or_corrupt() {
        let directory = tempfile::tempdir().unwrap();
        let missing = FileCredentialVault::new(directory.path().join("missing.json"));
        assert!(
            missing
                .resolve("credential-00000000-0000-0000-0000-000000000000")
                .is_err()
        );

        let corrupt = directory.path().join("corrupt.json");
        std::fs::write(&corrupt, b"not json").unwrap();
        let vault = FileCredentialVault::new(&corrupt);
        assert!(
            vault
                .resolve("credential-00000000-0000-0000-0000-000000000000")
                .is_err()
        );
    }

    #[cfg(not(target_os = "macos"))]
    #[test]
    fn corrupt_file_is_never_overwritten_by_an_empty_map() {
        let directory = tempfile::tempdir().unwrap();
        let corrupt = directory.path().join("corrupt.json");
        std::fs::write(&corrupt, b"not json").unwrap();
        let vault = FileCredentialVault::new(&corrupt);
        // 损坏文件存在期间：写入与删除都必须拒绝，不得静默覆盖丢密钥
        assert!(vault.insert(Secret::new("test-only-key")).is_err());
        assert!(vault.remove("credential-00000000-0000-0000-0000-000000000000").is_err());
        assert_eq!(std::fs::read(&corrupt).unwrap(), b"not json");
    }
}

//! 模型缓存管理与下载（llama.cpp Qwen3-ASR GGUF）。
//!
//! 默认目录：`~/.cache/course2md/models/`（可用 `--model-dir` / `models download --dir` 覆盖）
//!
//! ```text
//! models/
//!   llama-qwen3-1.7b/
//!     Qwen3-ASR-1.7B-Q8_0.gguf
//!     mmproj-Qwen3-ASR-1.7B-Q8_0.gguf
//! ```

use anyhow::{Context, Result};
use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};

#[path = "model_status.rs"]
pub mod status;

/// Normalize Apple model names without requiring the native Apple runtime.
/// Configuration and cache inspection also need these names on other platforms.
/// 精确别名表（不再用子串猜测，未知输入一律报错）；调用方仍须验证后端支持。
pub fn normalize_apple_model(s: &str) -> Result<String> {
    let s = s.trim().to_ascii_lowercase();
    match s.as_str() {
        "" | "qwen" | "qwen3" | "1.7" | "1.7b" | "qwen3-1.7b" | "qwen3-asr-1.7b"
        | "qwen3-asr-1.7b-q8_0.gguf" => Ok("qwen3-1.7b".into()),
        "0.6" | "0.6b" | "qwen3-0.6b" | "qwen3-asr-0.6b" => Ok("qwen3-0.6b".into()),
        "whisper" | "whisper-large-v3-turbo" => Ok("whisper".into()),
        _ => anyhow::bail!(
            "未知的 Apple 模型 / Unknown Apple model: `{s}`. 请选择 / Choose: qwen3-1.7b, qwen3-0.6b, whisper"
        ),
    }
}

/// Retrieve missing local model files before a large media download. Cached weights are
/// loaded by the later transcription stage; subtitle-only work never calls this function.
pub async fn ensure_cache(
    provider: crate::config::AsrProvider,
    model: &str,
    root: &Path,
) -> Result<()> {
    use crate::config::AsrProvider;
    let status = status::inspect(provider, model, root)?;
    anyhow::ensure!(
        status.can_prepare,
        "当前识别方式不支持这个模型，原任务参数已保留 / The current transcription backend does not support this model; task settings kept"
    );
    if matches!(
        status.state,
        status::CacheState::Cached | status::CacheState::Loaded
    ) {
        return Ok(());
    }
    match provider {
        AsrProvider::Cpu | AsrProvider::Gpu => download_models(root).await,
        AsrProvider::Coreml => {
            #[cfg(apple_native)]
            {
                let model = model.to_owned();
                tokio::task::spawn_blocking(move || crate::apple::prepare_cache(&model))
                    .await
                    .context("模型缓存准备未完成 / Model cache preparation did not complete")?
            }
            #[cfg(not(apple_native))]
            {
                Err(anyhow::anyhow!("此程序未包含 Apple 原生识别运行时 / This build does not include the Apple native transcription runtime"))
            }
        }
        AsrProvider::Npu => {
            let model = crate::npu::resolve_npu_model(Some(model));
            tokio::task::spawn_blocking(move || crate::npu::prepare_npu_model(&model))
                .await
                .context("NPU 模型准备未完成 / NPU model preparation did not complete")?
        }
        AsrProvider::Api => Ok(()),
    }
}

/// Prepare the exact selected backend without sending course content or changing settings.
pub async fn prepare(
    provider: crate::config::AsrProvider,
    model: &str,
    root: &Path,
) -> Result<status::LocalModelStatus> {
    use crate::config::AsrProvider;
    let before = status::inspect(provider, model, root)?;
    anyhow::ensure!(
        before.can_prepare,
        "这种识别方式不支持所选模型，请明确选择其他模型 / This transcription backend does not support the selected model; explicitly choose another model"
    );
    crate::progress::stage("model/prepare", "start");
    let result = match provider {
        AsrProvider::Cpu | AsrProvider::Gpu => download_models(root).await,
        AsrProvider::Coreml => {
            #[cfg(apple_native)]
            {
                let model = model.to_owned();
                let cached = matches!(
                    before.state,
                    status::CacheState::Cached | status::CacheState::Loaded
                );
                tokio::task::spawn_blocking(move || {
                    if !cached {
                        crate::apple::prepare_cache(&model)?;
                    }
                    crate::apple::prepare_model(&model)
                })
                .await
                .context("模型准备进程未完成 / Model preparation process did not complete")?
            }
            #[cfg(not(apple_native))]
            {
                Err(anyhow::anyhow!("此转换程序未包含 Apple 原生识别运行时 / This build does not include the Apple native transcription runtime"))
            }
        }
        AsrProvider::Npu => {
            let model = crate::npu::resolve_npu_model(Some(model));
            tokio::task::spawn_blocking(move || crate::npu::prepare_npu_model(&model))
                .await
                .context("NPU 模型准备进程未完成 / NPU model preparation process did not complete")?
        }
        // 依赖上游过滤不变量：inspect() 对 Api 返回 can_prepare=false，
        // prepare 入口的 ensure!(can_prepare) 已拦截；若上游过滤改动此处会变成 panic。
        AsrProvider::Api => unreachable!(),
    };
    let after = status::inspect(provider, model, root).unwrap_or_else(|error| {
        tracing::warn!("模型二次检查失败，沿用准备前状态 / Post-prepare inspection failed; keeping the pre-prepare status: {error:#}");
        before
    });
    let loaded = result.is_ok() && matches!(provider, AsrProvider::Coreml | AsrProvider::Npu);
    let error = result.as_ref().err().map(|error| format!("{error:#}"));
    if let Err(error) = status::record_result(&after, loaded, error) {
        tracing::warn!("模型检查结果暂时无法保存 / Could not save the model check result: {error:#}");
    }
    result?;
    crate::progress::stage("model/prepare", "done");
    status::inspect(provider, model, root)
}

const HF_REPO_PATH: &str = "ggml-org/Qwen3-ASR-1.7B-GGUF/resolve/main";

/// llama GGUF 模型 slug：模型目录名由它派生，身份字符串与它同源
///（concat! 不接受常量，身份字符串用字面量 + 测试守住一致性）。
const LLAMA_MODEL_SLUG: &str = crate::config::DEFAULT_ASR_MODEL;
const LLAMA_GGUF_IDENTITY: &str = "qwen3-1.7b-gguf";
const LLAMA_MODEL_FILE: &str = "Qwen3-ASR-1.7B-Q8_0.gguf";
const LLAMA_MMPROJ_FILE: &str = "mmproj-Qwen3-ASR-1.7B-Q8_0.gguf";

/// 当前 llama GGUF 模型的身份字符串（checkpoint/日志用），与模型目录同源。
pub fn llama_gguf_identity() -> &'static str {
    LLAMA_GGUF_IDENTITY
}

/// Hugging Face 端点：尊重 HF_ENDPOINT 镜像（与 CoreML 路径行为一致）。
/// 此前 GGUF 下载硬编码 huggingface.co，网络受限环境（如 Windows 直连
/// 失败）设置镜像也无效（issue #2）。
fn hf_base(endpoint: Option<String>) -> String {
    endpoint
        .map(|s| s.trim().trim_end_matches('/').to_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "https://huggingface.co".into())
}

fn current_hf_endpoint() -> Option<String> {
    std::env::var("HF_ENDPOINT").ok()
}

#[derive(Debug, Clone)]
pub struct LlamaAsr {
    pub model: PathBuf,
    pub mmproj: PathBuf,
}

pub fn llama_paths(root: &Path) -> LlamaAsr {
    let d = root.join(format!("llama-{LLAMA_MODEL_SLUG}"));
    LlamaAsr {
        model: d.join(LLAMA_MODEL_FILE),
        mmproj: d.join(LLAMA_MMPROJ_FILE),
    }
}

pub fn llama_ready(root: &Path) -> bool {
    let p = llama_paths(root);
    file_complete(&p.model) && file_complete(&p.mmproj)
}

/// 文件完整性：有 manifest（下载完成时记录的精确字节数）时按字节数校验；
/// 无 manifest 的旧缓存检查合法 GGUF 文件头及最小大小；这不等于模型已加载成功。
fn file_complete(path: &Path) -> bool {
    let Ok(md) = fs::metadata(path) else {
        return false;
    };
    // >1MB 启发式：GGUF 合法文件头（magic + 版本 + 张量元数据索引）加上任何
    // 可用权重都远超 1MB；≤1MB 必是截断残留或代理/镜像返回的错误页面。
    if !path.is_file() || md.len() <= 1_000_000 {
        return false;
    }
    let mut header = [0_u8; 8];
    if fs::File::open(path)
        .and_then(|mut file| file.read_exact(&mut header))
        .is_err()
        || &header[..4] != b"GGUF"
        || !matches!(u32::from_le_bytes(header[4..].try_into().unwrap()), 2 | 3)
    {
        return false;
    }
    let manifest = path.with_extension("manifest.json");
    if let Ok(s) = fs::read_to_string(&manifest)
        && let Ok(v) = serde_json::from_str::<serde_json::Value>(&s)
        && let Some(expected) = v.get("size").and_then(|s| s.as_u64())
    {
        return md.len() == expected;
    }
    true
}

pub fn ensure_llama(root: &Path) -> Result<LlamaAsr> {
    if !llama_ready(root) {
        anyhow::bail!(
            "缺少识别模型 / Speech models missing. 运行 / Run: course2md models download\n目录 / Directory: {}",
            root.display()
        );
    }
    Ok(llama_paths(root))
}

/// 没有模型就下载；下载过程请保持进程运行。
pub async fn ensure_llama_or_download(root: &Path) -> Result<LlamaAsr> {
    if !llama_ready(root) {
        if !crate::progress::is_json() && !crate::progress::is_quiet() {
            eprintln!(
                "正在下载识别模型（约 2.4GB）/ Downloading speech models (~2.4GB): {}",
                root.display()
            );
        }
        download_models(root).await?;
    }
    Ok(llama_paths(root))
}

/// 下载失败的附加提示：未设镜像时提示 HF_ENDPOINT（直连 Hugging Face
/// 不稳定是常见失败原因）；已设镜像则回显当前端点便于排查。
fn mirror_hint() -> String {
    match current_hf_endpoint() {
        Some(ep) => format!("下载失败 / Download failed (HF_ENDPOINT={ep})"),
        None => "下载失败，请检查网络或配置镜像 / Download failed; check your connection or configure a mirror: \
                 HF_ENDPOINT=https://hf-mirror.com"
            .into(),
    }
}

/// 下载 llama.cpp Qwen3-ASR GGUF。
pub async fn download_models(root: &Path) -> Result<()> {
    fs::create_dir_all(root)?;
    let _download_lock = crate::runtime::lock_file(&root.join(".download.lock"))?;
    let p = llama_paths(root);
    let base = hf_base(current_hf_endpoint());
    tracing::info!(endpoint = %base, "huggingface endpoint");
    let model_url = format!("{base}/{HF_REPO_PATH}/{LLAMA_MODEL_FILE}");
    let projector_url = format!("{base}/{HF_REPO_PATH}/{LLAMA_MMPROJ_FILE}");
    let (model, projector) = tokio::join!(
        download_file(&model_url, &p.model, LLAMA_MODEL_FILE),
        download_file(&projector_url, &p.mmproj, LLAMA_MMPROJ_FILE),
    );
    model.with_context(mirror_hint)?;
    projector.with_context(mirror_hint)?;
    anyhow::ensure!(
        llama_ready(root),
        "下载文件不是完整的 GGUF 模型，已有文件已保留，可以重试准备 / The downloaded file is not a complete GGUF model; existing files kept, preparation can be retried"
    );
    tracing::info!(path = %root.display(), "models ready");
    Ok(())
}

/// 下载重试次数（2.4GB 大文件，网络抖动/代理断流常见）。
const DOWNLOAD_ATTEMPTS: usize = 3;

/// 4xx（除 429 限流）是确定性错误（鉴权失败/路径错/镜像缺文件），
/// 退避重试无意义——来自 PR #9 的重试分类思路。
fn is_permanent_status(code: u16) -> bool {
    code != 429 && (400..500).contains(&code)
}

/// 确定性 HTTP 错误标记：重试循环见此类型直接失败。
#[derive(Debug)]
struct PermanentHttp(String);

impl std::fmt::Display for PermanentHttp {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for PermanentHttp {}

async fn download_file(url: &str, dest: &Path, label: &str) -> Result<()> {
    if dest.is_file() && file_complete(dest) {
        tracing::info!(label, "skip existing");
        return Ok(());
    }
    if dest.is_file() {
        // 校验不过的残留文件（截断/损坏）直接移除，避免"发现坏了却重下不了"
        tracing::warn!(
            label,
            "模型文件不完整，正在重新下载 / Model file incomplete; downloading again"
        );
        let _ = fs::remove_file(dest);
        let _ = fs::remove_file(dest.with_extension("manifest.json"));
    }
    if let Some(p) = dest.parent() {
        fs::create_dir_all(p)?;
    }
    let tmp = dest.with_extension("part");
    let url = url.to_string();
    let dest = dest.to_path_buf();
    let label = label.to_string();
    let stage = format!("model/{label}");
    crate::progress::stage(&stage, "start");
    tokio::task::spawn_blocking(move || -> Result<()> {
        // 只设连接/读超时，不设整体超时：2.4GB 大文件下完为止，
        // 读超时 10 分钟无数据视为挂起
        let agent = ureq::AgentBuilder::new()
            .timeout_connect(std::time::Duration::from_secs(30))
            .timeout_read(std::time::Duration::from_secs(600))
            .build();
        let mut last_err: Option<anyhow::Error> = None;
        for attempt in 1..=DOWNLOAD_ATTEMPTS {
            if attempt > 1 {
                let wait = std::time::Duration::from_secs(1 << (attempt - 1)); // 2s、4s 指数退避
                tracing::warn!(
                    label = %label,
                    attempt,
                    of = DOWNLOAD_ATTEMPTS,
                    ?wait,
                    "下载失败，稍后重试 / Download failed; retrying shortly"
                );
                std::thread::sleep(wait);
            }
            match download_once(&agent, &url, &tmp, &dest, &label) {
                Ok(()) => return Ok(()),
                Err(e) => {
                    // 确定性 HTTP 错误（4xx≠429）不再退避重试
                    if e.downcast_ref::<PermanentHttp>().is_some() {
                        return Err(e);
                    }
                    // 保留 .part：日志给出断点位置；当前实现重跑会从头下载
                    tracing::warn!(
                        label = %label,
                        part = %tmp.display(),
                        "下载失败，重试将从头下载 / Download failed; retrying starts a fresh download: {e:#}"
                    );
                    last_err = Some(e);
                }
            }
        }
        Err(last_err.unwrap_or_else(|| anyhow::anyhow!("模型下载失败 / Model download failed")))
    })
    .await
    .context("模型下载任务失败 / Model download task failed")??;
    crate::progress::stage(&stage, "done");
    Ok(())
}

/// 单次下载尝试：成功时原子落盘 dest 并写 manifest；失败保留 .part 供排查。
fn download_once(
    agent: &ureq::Agent,
    url: &str,
    tmp: &Path,
    dest: &Path,
    label: &str,
) -> Result<()> {
    tracing::info!(label = %label, url = %url, "download");
    let resp = match agent.get(url).call() {
        Ok(r) => r,
        Err(ureq::Error::Status(code, resp)) => {
            // 错误信息携带响应体尾部（服务器返回的错误页/JSON 通常是排查关键）
            let body = resp.into_string().unwrap_or_default();
            let n = body.chars().count();
            let tail: String = body.chars().skip(n.saturating_sub(200)).collect();
            let msg = format!("HTTP {code}: {tail}");
            if is_permanent_status(code) {
                return Err(anyhow::anyhow!(PermanentHttp(msg)));
            }
            return Err(anyhow::anyhow!(
                "模型请求失败 / Model request failed: {msg}"
            ));
        }
        Err(e) => return Err(anyhow::Error::new(e).context("模型请求失败 / Model request failed")),
    };
    let total: u64 = resp
        .header("content-length")
        .and_then(|v| v.parse().ok())
        .unwrap_or(0);
    let pb = crate::progress::Bar::new(format!("model/{label}"), total)
        .with_template("{spinner:.green} {msg} [{bar:32.cyan/blue}] {bytes}/{total_bytes} ({eta})");
    pb.set_message(label.to_string());
    let mut reader = resp.into_reader();
    let mut out = fs::File::create(tmp)?;
    let mut buf = vec![0u8; 1024 * 512];
    let mut done: u64 = 0;
    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 {
            break;
        }
        std::io::Write::write_all(&mut out, &buf[..n])?;
        done += n as u64;
        pb.set_position(done);
    }
    out.sync_all()?;
    drop(out);
    // 完整性：以服务器 Content-Length 为准（而非"实际收到多少"——截断响应会伪装成功）；
    // 不完整时保留 .part（断点位置见上方日志）
    if total > 0 && done != total {
        pb.finish();
        anyhow::bail!(
            "下载不完整，请重试 / Incomplete download; retry (expected {total} bytes, received {done})"
        );
    }
    fs::rename(tmp, dest)?;
    // manifest 记录 authoritative Content-Length，供后续启动校验（原子写，防半截 JSON）
    let _ = crate::checkpoint::atomic_write(
        &dest.with_extension("manifest.json"),
        serde_json::json!({"size": if total > 0 { total } else { done }})
            .to_string()
            .as_bytes(),
    );
    pb.finish();
    tracing::info!(label = %label, bytes = done, "downloaded");
    Ok(())
}

pub fn list_models(root: &Path) {
    let p = llama_paths(root);
    println!(
        "gpu/cpu 模型目录 / gpu/cpu model directory: {}",
        root.display()
    );
    println!(
        "  model  {} {}",
        if file_complete(&p.model) {
            "就绪 / Ready"
        } else {
            "缺失或不完整 / Missing or incomplete"
        },
        p.model.display()
    );
    println!(
        "  mmproj {} {}",
        if file_complete(&p.mmproj) {
            "就绪 / Ready"
        } else {
            "缺失或不完整 / Missing or incomplete"
        },
        p.mmproj.display()
    );
    if !llama_ready(root) {
        println!(
            "下载或修复 / Download or repair: course2md models download --dir {:?}",
            root
        );
    }
    println!(
        "Apple 和 NPU 模型由各自后端管理 / Apple and NPU models are managed by their backends."
    );
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn apple_model_names_are_available_without_the_native_runtime() {
        for (alias, canonical) in [
            ("", "qwen3-1.7b"),
            (" QWEN3-ASR-1.7B ", "qwen3-1.7b"),
            ("qwen3-asr-0.6b", "qwen3-0.6b"),
            ("Whisper-Large-v3-Turbo", "whisper"),
        ] {
            assert_eq!(normalize_apple_model(alias).unwrap(), canonical);
        }
        assert!(normalize_apple_model("unsupported-model").is_err());
        // 子串猜测不再生效：含关键词的未知输入必须报错而不是静默误映射
        assert!(normalize_apple_model("foo-0.6-bar").is_err());
        assert!(normalize_apple_model("whisper-0.6").is_err());
    }

    #[test]
    fn interrupted_and_unknown_size_downloads_only_publish_complete_files() {
        use std::{
            io::{Read, Write},
            net::TcpListener,
        };
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            for response in [
                "HTTP/1.1 200 OK\r\nContent-Length: 6\r\nConnection: close\r\n\r\nabc",
                "HTTP/1.1 200 OK\r\nConnection: close\r\n\r\nabcdef",
                "HTTP/1.1 200 OK\r\nContent-Length: 5\r\nConnection: close\r\n\r\n12345",
            ] {
                let (mut stream, _) = listener.accept().unwrap();
                stream
                    .set_read_timeout(Some(std::time::Duration::from_secs(3)))
                    .unwrap();
                let mut request = Vec::new();
                while !request.ends_with(b"\r\n\r\n") {
                    let mut byte = [0];
                    if stream.read(&mut byte).unwrap() == 0 {
                        break;
                    }
                    request.push(byte[0]);
                }
                stream.write_all(response.as_bytes()).unwrap();
            }
        });
        let root = tempfile::tempdir().unwrap();
        let temporary = root.path().join("model.part");
        let destination = root.path().join("model.bin");
        let agent = ureq::AgentBuilder::new()
            .timeout(std::time::Duration::from_secs(3))
            .build();
        let url = format!("http://{address}/model");
        assert!(download_once(&agent, &url, &temporary, &destination, "synthetic").is_err());
        assert!(!destination.exists());
        assert_eq!(fs::read(&temporary).unwrap(), b"abc");
        download_once(&agent, &url, &temporary, &destination, "synthetic").unwrap();
        assert_eq!(fs::read(&destination).unwrap(), b"abcdef");
        let manifest: serde_json::Value =
            serde_json::from_slice(&fs::read(destination.with_extension("manifest.json")).unwrap())
                .unwrap();
        assert_eq!(manifest["size"], 6);
        assert!(!temporary.exists());
        let known = root.path().join("known.bin");
        download_once(&agent, &url, &temporary, &known, "synthetic").unwrap();
        assert_eq!(fs::read(&known).unwrap(), b"12345");
        server.join().unwrap();
        let missing = root.path().join("offline.bin");
        assert!(download_once(&agent, &url, &temporary, &missing, "synthetic").is_err());
        assert!(!missing.exists());
        assert_eq!(fs::read(destination).unwrap(), b"abcdef");
    }

    #[test]
    fn identity_matches_dir_slug() {
        // LLAMA_MODEL_SLUG 与 LLAMA_GGUF_IDENTITY 是两个独立字面量（concat! 不接受
        // 常量，无法互相派生），这里用字面量期望值锁定两者的对应关系，防止改名时只改一处。
        assert_eq!(llama_gguf_identity(), "qwen3-1.7b-gguf");
        assert!(
            llama_paths(Path::new("/x"))
                .model
                .starts_with("/x/llama-qwen3-1.7b")
        );
    }

    #[test]
    fn hf_endpoint_mirror_is_honored() {
        assert_eq!(hf_base(None), "https://huggingface.co");
        assert_eq!(
            hf_base(Some("https://hf-mirror.com".into())),
            "https://hf-mirror.com"
        );
        // 尾部斜杠归一；空白视为未设置
        assert_eq!(
            hf_base(Some("https://hf-mirror.com/".into())),
            "https://hf-mirror.com"
        );
        assert_eq!(hf_base(Some("  ".into())), "https://huggingface.co");
    }

    #[test]
    fn permanent_status_classification() {
        // 确定性错误：不重试
        for code in [400, 401, 403, 404, 422] {
            assert!(is_permanent_status(code), "{code} 应直接失败");
        }
        // 429 限流与 5xx 服务端错误：值得退避重试
        for code in [429, 500, 502, 503] {
            assert!(!is_permanent_status(code), "{code} 应重试");
        }
    }
}

//! Read-only cache evidence. Finding files is deliberately distinct from loading a model.
use crate::config::AsrProvider;
use anyhow::{Context, Result, ensure};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{
    collections::BTreeSet,
    fs,
    path::{Path, PathBuf},
    time::{SystemTime, UNIX_EPOCH},
};

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum CacheState {
    Missing,
    Partial,
    Cached,
    Loaded,
    Unsupported,
}
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct CachePart {
    pub name: String,
    pub path: PathBuf,
    pub bytes: u64,
    pub missing: Vec<String>,
}
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct LocalModelStatus {
    pub provider: AsrProvider,
    pub model: String,
    pub state: CacheState,
    pub parts: Vec<CachePart>,
    pub bytes: u64,
    pub can_prepare: bool,
    pub last_error: Option<String>,
    pub loaded_at: Option<u64>,
    pub fingerprint: String,
}
#[derive(Clone, Serialize, Deserialize)]
struct Receipt {
    fingerprint: String,
    loaded_at: Option<u64>,
    last_error: Option<String>,
    version: String,
}

pub fn inspect(provider: AsrProvider, model: &str, root: &Path) -> Result<LocalModelStatus> {
    let home = std::env::var_os("HOME")
        .or_else(|| std::env::var_os("USERPROFILE"))
        .map(PathBuf::from)
        .unwrap_or_else(crate::config::cache_dir);
    let apple_base = ["QWEN3_CACHE_DIR", "QWEN3_ASR_CACHE_DIR"]
        .into_iter()
        .find_map(|key| {
            std::env::var_os(key)
                .filter(|value| !value.is_empty())
                .map(PathBuf::from)
        })
        .unwrap_or_else(|| home.join("Library/Caches"))
        .join("qwen3-speech");
    let hf_base = ["HF_HUB_CACHE", "HUGGINGFACE_HUB_CACHE"]
        .into_iter()
        .find_map(|key| {
            std::env::var_os(key)
                .filter(|value| !value.is_empty())
                .map(PathBuf::from)
        })
        .unwrap_or_else(|| {
            std::env::var_os("HF_HOME")
                .map(PathBuf::from)
                .unwrap_or_else(|| home.join(".cache/huggingface"))
                .join("hub")
        });
    let mut status = inspect_at(provider, model, root, &apple_base, &hf_base)?;
    if let Ok(bytes) = fs::read(receipt_path(&status))
        && let Ok(receipt) = serde_json::from_slice::<Receipt>(&bytes)
    {
        status.last_error = receipt.last_error;
        if status.state == CacheState::Cached
            && receipt.fingerprint == status.fingerprint
            && receipt.version == env!("CARGO_PKG_VERSION")
        {
            status.loaded_at = receipt.loaded_at;
            if receipt.loaded_at.is_some() {
                status.state = CacheState::Loaded;
            }
        }
    }
    Ok(status)
}

/// Explicit roots make cache checks testable without inspecting the user's model directory.
pub fn inspect_at(
    provider: AsrProvider,
    model: &str,
    root: &Path,
    apple_base: &Path,
    hf_base: &Path,
) -> Result<LocalModelStatus> {
    let model = if model.trim().is_empty() {
        crate::config::DEFAULT_ASR_MODEL
    } else {
        model.trim()
    };
    let mut parts = Vec::new();
    let supported = match provider {
        AsrProvider::Cpu | AsrProvider::Gpu => model == crate::config::DEFAULT_ASR_MODEL,
        AsrProvider::Coreml => ["qwen3-1.7b", "qwen3-0.6b", "whisper"].contains(&model),
        AsrProvider::Npu => !model.is_empty(),
        AsrProvider::Api => false,
    };
    if !supported {
        return Ok(LocalModelStatus {
            provider,
            model: model.into(),
            state: CacheState::Unsupported,
            parts,
            bytes: 0,
            can_prepare: false,
            last_error: None,
            loaded_at: None,
            fingerprint: String::new(),
        });
    }
    match provider {
        AsrProvider::Cpu | AsrProvider::Gpu => {
            let files = super::llama_paths(root);
            let path = files.model.parent().unwrap().to_path_buf();
            let mut missing = Vec::new();
            for file in [&files.model, &files.mmproj] {
                if !super::file_complete(file) || !gguf_header(file) {
                    missing.push(file.file_name().unwrap().to_string_lossy().into_owned());
                }
            }
            parts.push(cache_part("Qwen3-ASR 1.7B Q8_0", path, missing)?);
        }
        AsrProvider::Coreml => {
            match model {
                "qwen3-1.7b" => parts.push(apple_part(
                    apple_base,
                    "aufklarer/Qwen3-ASR-1.7B-MLX-8bit",
                    &[
                        "config.json",
                        "vocab.json",
                        "merges.txt",
                        "tokenizer_config.json",
                    ],
                    &[],
                    true,
                )?),
                "qwen3-0.6b" => {
                    parts.push(apple_part(
                        apple_base,
                        "aufklarer/Qwen3-ASR-CoreML",
                        &["config.json"],
                        &[
                            "encoder.mlmodelc",
                            "embedding.mlmodelc",
                            "decoder_part1.mlmodelc",
                            "decoder_part2.mlmodelc",
                        ],
                        false,
                    )?);
                    parts.push(apple_part(
                        apple_base,
                        "aufklarer/Qwen3-ASR-0.6B-MLX-4bit",
                        &["vocab.json", "merges.txt", "tokenizer_config.json"],
                        &[],
                        true,
                    )?);
                }
                "whisper" => parts.push(apple_part(
                    apple_base,
                    "aufklarer/Whisper-Large-v3-Turbo-CoreML",
                    &[
                        "generation_config.json",
                        "tokenizer.json",
                        "tokenizer_config.json",
                    ],
                    &[
                        "MelSpectrogram.mlmodelc",
                        "AudioEncoder.mlmodelc",
                        "TextDecoder.mlmodelc",
                        "TextDecoderContextPrefill.mlmodelc",
                    ],
                    false,
                )?),
                _ => unreachable!(),
            }
            parts.push(apple_part(
                apple_base,
                "aufklarer/Silero-VAD-v6.2.1-CoreML",
                &["config.json"],
                &["silero_vad.mlmodelc"],
                false,
            )?);
        }
        AsrProvider::Npu => {
            let repo = crate::npu::resolve_npu_model(Some(model));
            let root = if Path::new(&repo).is_absolute() {
                PathBuf::from(&repo)
            } else {
                hf_base.join(format!("models--{}", repo.replace('/', "--")))
            };
            let path = if root.join("refs/main").is_file() {
                let revision = fs::read_to_string(root.join("refs/main"))?;
                let revision = revision.trim();
                ensure!(
                    !revision.is_empty()
                        && revision
                            .chars()
                            .all(|c| c.is_ascii_alphanumeric() || c == '-'),
                    "NPU 缓存版本记录无效 / Invalid NPU cache version record"
                );
                root.join("snapshots").join(revision)
            } else {
                root
            };
            let files = files_under(&path)?;
            let xml = files
                .iter()
                .filter(|file| file.extension().is_some_and(|extension| extension == "xml"))
                .collect::<Vec<_>>();
            let mut missing = Vec::new();
            if xml.is_empty() {
                missing.push("OpenVINO 模型 XML 和权重 / OpenVINO model XML and weights".into());
            }
            for file in xml {
                if !nonempty(&file.with_extension("bin")) {
                    missing.push(file.with_extension("bin").display().to_string());
                }
            }
            parts.push(cache_part(&repo, path, missing)?);
        }
        // 依赖上游过滤不变量：inspect() 对 Api 置 supported=false 并已提前返回，
        // 走不到这里；若上游过滤改动此处会变成 panic。
        AsrProvider::Api => unreachable!(),
    }
    let bytes = parts.iter().map(|part| part.bytes).sum();
    let missing = parts.iter().any(|part| !part.missing.is_empty());
    let state = if bytes == 0 {
        CacheState::Missing
    } else if missing {
        CacheState::Partial
    } else {
        CacheState::Cached
    };
    let mut hash = Sha256::new();
    hash.update(provider.as_str());
    hash.update(model);
    for part in &parts {
        hash.update(part.path.to_string_lossy().as_bytes());
        for file in files_under(&part.path)? {
            let metadata = fs::metadata(&file)?;
            hash.update(
                file.strip_prefix(&part.path)
                    .unwrap_or(&file)
                    .to_string_lossy()
                    .as_bytes(),
            );
            hash.update(metadata.len().to_le_bytes());
            hash.update(
                metadata
                    .modified()?
                    .duration_since(UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_nanos()
                    .to_le_bytes(),
            );
        }
    }
    Ok(LocalModelStatus {
        provider,
        model: model.into(),
        state,
        parts,
        bytes,
        can_prepare: true,
        last_error: None,
        loaded_at: None,
        fingerprint: format!("{:x}", hash.finalize()),
    })
}
fn cache_part(name: &str, path: PathBuf, missing: Vec<String>) -> Result<CachePart> {
    let bytes = files_under(&path)?
        .into_iter()
        .map(|path| fs::metadata(path).map(|metadata| metadata.len()))
        .collect::<std::io::Result<Vec<_>>>()?
        .into_iter()
        .sum();
    Ok(CachePart {
        name: name.into(),
        path,
        bytes,
        missing,
    })
}
fn apple_part(
    base: &Path,
    repo: &str,
    files: &[&str],
    bundles: &[&str],
    weights: bool,
) -> Result<CachePart> {
    let old = base.join(repo.replace('/', "_"));
    // Match speech-swift's directory choice exactly, then independently assess file
    // completeness. Its legacy probe accepts bundle markers, but rejects missing shards.
    let path = if apple_uses_legacy_cache(&old)? {
        old
    } else {
        base.join("models").join(repo)
    };
    let mut missing = files
        .iter()
        .filter(|file| !nonempty(&path.join(file)))
        .map(|file| (*file).into())
        .collect::<Vec<String>>();
    for bundle in bundles {
        let payload = files_under(&path.join(bundle))?;
        if !payload.iter().any(|path| {
            path.extension()
                .is_some_and(|extension| extension == "bin" || extension == "mil")
                && nonempty(path)
        }) {
            missing.push(format!("{bundle} 的模型内容 / model content of {bundle}"));
        }
    }
    if weights {
        let index = path.join("model.safetensors.index.json");
        if index.is_file() {
            match fs::read(index)
                .ok()
                .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok())
                .and_then(|value| {
                    value
                        .get("weight_map")
                        .and_then(|map| map.as_object())
                        .cloned()
                }) {
                Some(map) if !map.is_empty() => {
                    for file in map
                        .values()
                        .filter_map(|value| value.as_str())
                        .collect::<BTreeSet<_>>()
                    {
                        if !safe_tensor(&path.join(file)) {
                            missing.push(file.into());
                        }
                    }
                }
                _ => missing.push("有效的模型分片索引 / a valid model shard index".into()),
            }
        } else if !files_under(&path)?.iter().any(|file| {
            file.extension()
                .is_some_and(|extension| extension == "safetensors")
                && safe_tensor(file)
        }) {
            missing.push("完整的 safetensors 权重文件 / a complete safetensors weight file".into());
        }
    }
    cache_part(repo, path, missing)
}
fn apple_uses_legacy_cache(path: &Path) -> Result<bool> {
    if !path.exists() {
        return Ok(false);
    }
    let entries = fs::read_dir(path)
        .with_context(|| {
            format!(
                "无法读取模型缓存 / Cannot read the model cache: {}",
                path.display()
            )
        })?
        .collect::<std::io::Result<Vec<_>>>()?;
    if !entries.iter().any(|entry| {
        entry.path().extension().is_some_and(|extension| {
            ["safetensors", "mlmodelc", "mlpackage"]
                .iter()
                .any(|value| extension == *value)
        })
    }) {
        return Ok(false);
    }
    if let Ok(bytes) = fs::read(path.join("model.safetensors.index.json"))
        && let Ok(index) = serde_json::from_slice::<serde_json::Value>(&bytes)
        && let Some(map) = index.get("weight_map").and_then(|value| value.as_object())
        && map.values().all(|value| value.is_string())
        && map
            .values()
            .any(|value| !path.join(value.as_str().unwrap()).exists())
    {
        return Ok(false);
    }
    Ok(true)
}
fn nonempty(path: &Path) -> bool {
    path.is_file() && fs::metadata(path).is_ok_and(|metadata| metadata.len() > 0)
}
fn gguf_header(path: &Path) -> bool {
    use std::io::Read;
    let mut header = [0u8; 8];
    fs::File::open(path)
        .and_then(|mut file| file.read_exact(&mut header))
        .is_ok()
        && &header[..4] == b"GGUF"
        && matches!(u32::from_le_bytes(header[4..].try_into().unwrap()), 2 | 3)
}
fn safe_tensor(path: &Path) -> bool {
    use std::io::Read;
    let checked = || -> Result<bool> {
        let mut file = fs::File::open(path)?;
        let length = file.metadata()?.len();
        let mut header = [0; 8];
        file.read_exact(&mut header)?;
        let size = u64::from_le_bytes(header);
        ensure!(
            size > 0 && size < 16 * 1024 * 1024 && size + 8 < length,
            "权重头不完整 / Incomplete weight header"
        );
        let mut header = vec![0; size as usize];
        file.read_exact(&mut header)?;
        let value: serde_json::Value = serde_json::from_slice(&header)?;
        let tensors = value.as_object().context("权重索引无效 / Invalid weight index")?;
        let mut count = 0;
        for (key, tensor) in tensors {
            if key == "__metadata__" {
                continue;
            }
            let offsets = tensor
                .get("data_offsets")
                .and_then(|value| value.as_array())
                .context("权重偏移无效 / Invalid weight offsets")?;
            ensure!(
                offsets.len() == 2
                    && offsets[1]
                        .as_u64()
                        .is_some_and(|end| end <= length - size - 8),
                "权重文件不完整 / Incomplete weight file"
            );
            count += 1;
        }
        Ok(count > 0)
    };
    checked().unwrap_or(false)
}
fn files_under(root: &Path) -> Result<Vec<PathBuf>> {
    if !root.exists() {
        return Ok(Vec::new());
    }
    let mut queue = vec![root.to_path_buf()];
    let mut seen = BTreeSet::new();
    let mut result = Vec::new();
    while let Some(path) = queue.pop() {
        let canonical = path
            .canonicalize()
            .with_context(|| {
                format!(
                    "无法读取模型缓存 / Cannot read the model cache: {}",
                    path.display()
                )
            })?;
        if !seen.insert(canonical) {
            continue;
        }
        if path.is_dir() {
            for child in fs::read_dir(&path)? {
                queue.push(child?.path());
            }
        } else if path.is_file() {
            result.push(path);
        }
        ensure!(seen.len() < 20_000, "模型缓存包含过多文件，检查未完成 / Model cache contains too many files; check incomplete");
    }
    result.sort();
    Ok(result)
}
fn receipt_path(status: &LocalModelStatus) -> PathBuf {
    let key = format!(
        "{}:{}:{}",
        status.provider.as_str(),
        status.model,
        status
            .parts
            .iter()
            .map(|part| part.path.display().to_string())
            .collect::<Vec<_>>()
            .join("|")
    );
    crate::config::cache_dir()
        .join("model-checks")
        .join(format!("{:x}.json", Sha256::digest(key)))
}
pub fn record_result(status: &LocalModelStatus, loaded: bool, error: Option<String>) -> Result<()> {
    let receipt = Receipt {
        fingerprint: status.fingerprint.clone(),
        loaded_at: loaded.then(|| {
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs()
        }),
        last_error: error,
        version: env!("CARGO_PKG_VERSION").into(),
    };
    crate::checkpoint::atomic_write(&receipt_path(status), &serde_json::to_vec(&receipt)?)
}

#[cfg(test)]
mod tests {
