    /// One-line readiness conclusion for the generation group main flow; the full
    /// panel stays behind 技术详情.
    pub(super) fn default_model_conclusion(&self) -> (bool, String) {
        let request = self.default_model_request();
        if request.provider == AsrProvider::Api {
            return (true, "当前使用语音服务识别，本机模型不参与。".into());
        }
        if self.model_device_issue(request.provider).is_some() {
            return (
                false,
                "所选识别方式暂不可用，可在模型管理中查看原因。".into(),
            );
        }
        let entry = self
            .settings_ui
            .model_diagnostics
            .entries
            .get(&request.key());
        if entry.is_none_or(Entry::checking) {
            return (true, "正在检查识别模型…".into());
        }
        if entry
            .and_then(Entry::result)
            .is_some_and(Result::is_err)
        {
            return (
                false,
                "模型检查未完成，可在模型管理中查看原因并重试。".into(),
            );
        }
        match entry
            .and_then(Entry::result)
            .and_then(|result| result.as_ref().ok())
            .map(|status| &status.state)
        {
            Some(CacheState::Loaded) => (true, "识别模型已就绪。".into()),
            Some(CacheState::Cached) => (true, "模型已下载，尚未验证加载。".into()),
            Some(CacheState::Missing | CacheState::Partial) => {
                (true, "首次识别时会自动下载所选模型。".into())
            }
            Some(CacheState::Unsupported) => {
                (false, "当前识别方式不支持所选模型，请选择其他模型。".into())
            }
            None => (true, "尚未检查识别模型。".into()),
        }
    }
}

//! Read-only OpenAI-compatible model discovery, separate from service contract tests.
//! A listed model is a candidate, never evidence that a processing capability works.

use crate::credentials::{CredentialRef, CredentialVault, Secret};
use crate::preferences::{Authentication, ServiceDraft, ServiceProtocol, normalize_endpoint};
use std::collections::BTreeSet;
use std::future::Future;
use std::sync::{
    Arc,
    atomic::{AtomicBool, Ordering},
};
use std::time::{Duration, Instant};

const MAX_RESPONSE: u64 = 1024 * 1024;
const DISCOVERY_TIMEOUT: Duration = Duration::from_secs(20);

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Error {
    InvalidAddress,
    MissingKey,
    InvalidKey,
    CredentialUnavailable,
    TimedOut,
    Network,
    AuthenticationRefused,
    Unsupported,
    Refused(u16),
    InvalidResponse,
    TooLarge,
    /// A provider-specific failure with an already sanitized, user-readable message.
    Custom(String),
    Cancelled,
}

impl Error {
    pub fn message(&self) -> String {
        match self {
            Self::InvalidAddress => "请先填写有效的服务地址，再获取模型".into(),
            Self::MissingKey => "请先填写 API Key，再获取模型".into(),
            Self::InvalidKey => "API Key 含无效字符，请检查后重试".into(),
            Self::CredentialUnavailable => "暂时无法读取已保存的 API Key，可重新填写后重试".into(),
            Self::TimedOut => "获取模型超时，可重试或手动填写模型 ID".into(),
            Self::Network => "暂时无法获取模型，请检查地址或网络；也可手动填写模型 ID".into(),
            Self::AuthenticationRefused => {
                "服务拒绝访问模型列表，请检查认证设置；也可手动填写模型 ID".into()
            }
            Self::Unsupported => "服务未提供可读取的模型列表，可手动填写模型 ID".into(),
            Self::Refused(status) => {
                format!("暂时无法获取模型（HTTP {status}），可重试或手动填写模型 ID")
            }
            Self::InvalidResponse => "未能识别服务返回的模型列表，可手动填写模型 ID".into(),
            Self::TooLarge => "服务返回的模型列表过大，可手动填写模型 ID".into(),
            Self::Custom(message) => message.clone(),
            Self::Cancelled => "已取消获取模型，可手动填写模型 ID".into(),
        }
    }
}

#[derive(Clone, PartialEq, Eq)]
enum AuthIdentity {
    None,
    Saved(CredentialRef),
    // Never retain plaintext input in a request identity or diagnostic string.
    Typed(String),
}

#[derive(Clone, PartialEq, Eq)]
pub struct RequestKey {
    endpoint: String,
    protocol: ServiceProtocol,
    auth: AuthIdentity,
}

impl RequestKey {
    /// Reads only public configuration and the currently entered key. The model ID
    /// and display name do not affect a service's model list.
    pub fn from_draft(draft: &ServiceDraft, typed_key: &str) -> Result<Self, Error> {
        let endpoint = models_endpoint(&draft.address, draft.protocol)?;
        let typed_key = typed_key.trim();
        let auth = if draft.authentication == Authentication::None {
            AuthIdentity::None
        } else if !typed_key.is_empty() {
            if typed_key.chars().any(char::is_control) {
                return Err(Error::InvalidKey);
            }
            AuthIdentity::Typed(course2md::execution::digest(typed_key.as_bytes()))
        } else {
            AuthIdentity::Saved(draft.credential.clone().ok_or(Error::MissingKey)?)
        };
        Ok(Self {
            endpoint,
            protocol: draft.protocol,
            auth,
        })
    }
}

fn models_endpoint(address: &str, protocol: ServiceProtocol) -> Result<String, Error> {
    let endpoint = normalize_endpoint(address, protocol).map_err(|_| Error::InvalidAddress)?;
    let mut url = url::Url::parse(&endpoint).map_err(|_| Error::InvalidAddress)?;
    let base = url
        .path()
        .strip_suffix(protocol.endpoint_suffix())
        .ok_or(Error::InvalidAddress)?;
    let path = format!("{base}/models");
    url.set_path(&path);
    Ok(url.into())
}

pub struct Request {
    key: RequestKey,
    typed_key: Option<Secret>,
    cancelled: Arc<AtomicBool>,
}

impl Request {
    /// Discovery does not stage a draft, store a key or require a model ID.
    pub fn from_draft(draft: &ServiceDraft, typed_key: Secret) -> Result<Self, Error> {
        let key = RequestKey::from_draft(draft, typed_key.expose())?;
        let typed_key = matches!(&key.auth, AuthIdentity::Typed(_))
            .then(|| Secret::new(typed_key.expose().trim()));
        Ok(Self {
            key,
            typed_key,
            cancelled: Arc::new(AtomicBool::new(false)),
        })
    }

    #[cfg(test)]
    pub fn key(&self) -> &RequestKey {
        &self.key
    }
}

#[derive(Clone)]
pub struct Ticket {
    id: uuid::Uuid,
    key: RequestKey,
    cancelled: Arc<AtomicBool>,
}

#[derive(Default)]
pub enum Status {
    #[default]
    Idle,
    Loading,
    Ready(Vec<String>),
    Failed(Error),
}

#[derive(Default)]
pub struct State {
    active: Option<Ticket>,
    status: Status,
}

impl State {
    pub fn status(&self) -> &Status {
        &self.status
    }
    pub fn loading(&self) -> bool {
        matches!(self.status, Status::Loading)
    }
    pub fn models(&self) -> &[String] {
        match &self.status {
            Status::Ready(models) => models,
            _ => &[],
        }
    }
    pub fn invalidate(&mut self) {
        if let Some(active) = self.active.take() {
            active.cancelled.store(true, Ordering::Release);
        }
        self.status = Status::Idle;
    }
    /// Seed choices obtained without HTTP discovery (an account login's own catalog).
    /// There is no connection to invalidate; the next `invalidate` clears them.
    pub fn prime(&mut self, models: Vec<String>) {
        self.invalidate();
        self.status = Status::Ready(models);
    }
    /// Begin an externally driven fetch (no HTTP [`Request`]); complete with
    /// [`State::prime`] or [`State::reject`]. Gives the shared field its loading state.
    pub fn begin_external(&mut self) {
        self.invalidate();
        self.status = Status::Loading;
    }
    pub fn reject(&mut self, error: Error) {
        self.invalidate();
        self.status = Status::Failed(error);
    }
    pub fn begin(&mut self, request: &Request) -> Ticket {
        self.invalidate();
        let ticket = Ticket {
            id: uuid::Uuid::new_v4(),
            key: request.key.clone(),
            cancelled: request.cancelled.clone(),
        };
        self.active = Some(ticket.clone());
        self.status = Status::Loading;
        ticket
    }
    /// Recompute `current` from live inputs, not just an earlier change observer.
    /// This also rejects responses from a closed/reopened editor or a prior retry.
    pub fn complete(
        &mut self,
        ticket: Ticket,
        current: Option<&RequestKey>,
        result: Result<Vec<String>, Error>,
    ) -> bool {
        if !self.loading()
            || self
                .active
                .as_ref()
                .is_none_or(|active| active.id != ticket.id)
        {
            return false;
        }
        if current != Some(&ticket.key) || ticket.cancelled.load(Ordering::Acquire) {
            self.invalidate();
            return false;
        }
        // Keep the completed ticket as the lifetime of the displayed choices.
        // Invalidating the connection disables choices in an already-open menu.
        self.status = match result {
            Ok(models) => Status::Ready(models),
            Err(Error::Cancelled) => Status::Idle,
            Err(error) => Status::Failed(error),
        };
        true
    }
}

impl Drop for State {
    fn drop(&mut self) {
        self.invalidate();
    }
}

/// Uses the supplied draft's endpoint and authentication exactly once. Redirects
/// are disabled so authentication never follows a server to another endpoint.
/// The outer deadline also bounds waiting for the Keychain and system DNS.
pub async fn discover(
    request: Request,
    vault: Arc<dyn CredentialVault>,
) -> Result<Vec<String>, Error> {
    let deadline = Instant::now() + DISCOVERY_TIMEOUT;
    let work = smol::unblock(move || {
        run_discovery(
            request,
            vault.as_ref(),
            &HttpTransport { deadline },
            deadline,
            Instant::now,
        )
    });
    before_deadline(work, deadline).await
}

async fn before_deadline(
    work: impl Future<Output = Result<Vec<String>, Error>>,
    deadline: Instant,
) -> Result<Vec<String>, Error> {
    let result = smol::future::race(work, async {
        smol::Timer::at(deadline).await;
        Err(Error::TimedOut)
    })
    .await;
    // Both futures can become ready before this task is polled again. Never
    // accept a late result just because the worker won that poll's ordering.
    if Instant::now() >= deadline {
        return Err(Error::TimedOut);
    }
    // Do not cancel the UI ticket on timeout: it must accept the failure once.
    // A blocked OS call may finish later, but its dropped receiver cannot publish.
    result
}

fn remaining(deadline: Instant) -> Result<Duration, Error> {
    deadline
        .checked_duration_since(Instant::now())
        .filter(|duration| !duration.is_zero())
        .ok_or(Error::TimedOut)
}

struct Response {
    status: u16,
    body: Vec<u8>,
}
trait Transport {
    fn get(&self, endpoint: &str, authorization: Option<&Secret>) -> Result<Response, Error>;
}
struct HttpTransport {
    deadline: Instant,
}
impl Transport for HttpTransport {
    fn get(&self, endpoint: &str, authorization: Option<&Secret>) -> Result<Response, Error> {
        let budget = remaining(self.deadline)?;
        let agent = crate::bounded_http::json_agent(
            budget.min(Duration::from_secs(10)),
            budget.min(Duration::from_secs(15)),
            None,
            budget,
        );
        let call = crate::bounded_http::json_call(agent.get(endpoint), authorization);
        let response = match call.timeout(remaining(self.deadline)?).call() {
            Ok(response) | Err(ureq::Error::Status(_, response)) => response,
            Err(ureq::Error::Transport(_)) => return Err(Error::Network),
        };
        let status = response.status();
        let body = crate::bounded_http::read_bounded(response, MAX_RESPONSE).map_err(|error| {
            match error {
                crate::bounded_http::BoundedReadError::TooLarge => Error::TooLarge,
                crate::bounded_http::BoundedReadError::Network(_) => Error::Network,
            }
        })?;
        Ok(Response { status, body })
    }
}

fn run_discovery(
    request: Request,
    vault: &dyn CredentialVault,
    transport: &dyn Transport,
    deadline: Instant,
    now: impl Fn() -> Instant,
) -> Result<Vec<String>, Error> {
    let cancelled = request.cancelled.clone();
    let check = || {
        if cancelled.load(Ordering::Acquire) {
            Err(Error::Cancelled)
        } else if now() >= deadline {
            Err(Error::TimedOut)
        } else {
            Ok(())
        }
    };
    check()?;
    let authorization = match &request.key.auth {
        AuthIdentity::None => Ok(None),
        AuthIdentity::Typed(_) => Ok(request.typed_key),
        AuthIdentity::Saved(reference) => vault
            .resolve(reference)
            .map(Some)
            .map_err(|_| Error::CredentialUnavailable),
    };
    // A Keychain call cannot be interrupted while blocked. Once it returns,
    // an expired request must stop here before any network request is sent.
    check()?;
    let authorization = authorization?;
    if let Some(secret) = &authorization {
        if secret.is_empty() || secret.expose().chars().any(char::is_control) {
            return Err(Error::InvalidKey);
        }
    }
    check()?;
    let response = transport.get(&request.key.endpoint, authorization.as_ref());
    check()?;
    let response = response?;
    match response.status {
        200..=299 => (),
        401 | 403 => return Err(Error::AuthenticationRefused),
        300..=399 | 404 | 405 | 501 => return Err(Error::Unsupported),
        status => return Err(Error::Refused(status)),
    }
    let models = parse_models(&response.body, authorization.as_ref());
    check()?;
    models
}

fn parse_models(body: &[u8], authorization: Option<&Secret>) -> Result<Vec<String>, Error> {
    let value: serde_json::Value =
        serde_json::from_slice(body).map_err(|_| Error::InvalidResponse)?;
    let data = value
        .get("data")
        .and_then(serde_json::Value::as_array)
        .ok_or(Error::InvalidResponse)?;
    if value.get("error").is_some() {
        return Err(Error::InvalidResponse);
    }
    if data.len() > 10000 {
        return Err(Error::TooLarge);
    }
    let models: BTreeSet<String> = data
        .iter()
        .filter_map(|item| item.get("id")?.as_str())
        .map(str::trim)
        .filter(|id| !id.is_empty() && id.len() <= 512 && !id.chars().any(char::is_control))
        .filter(|id| authorization.is_none_or(|secret| !id.contains(secret.expose())))
        .map(str::to_owned)
        .collect();
    if !data.is_empty() && models.is_empty() {
        return Err(Error::InvalidResponse);
    }
    Ok(models.into_iter().collect())
}

/// Shared settings/setup model control. The input remains editable in every
/// discovery state; choosing a candidate emits its ordinary input-change event.
pub fn model_field(
    id: &'static str,
    input: &gpui::Entity<gpui_component::input::InputState>,
    state: &State,
    disabled: bool,
    on_fetch: impl Fn(&gpui::ClickEvent, &mut gpui::Window, &mut gpui::App) + 'static,
    cx: &mut gpui::App,
) -> gpui::Div {
    model_field_with_error(id, input, state, disabled, None, on_fetch, cx)
}

pub fn model_field_with_error(
    id: &'static str,
    input: &gpui::Entity<gpui_component::input::InputState>,
    state: &State,
    disabled: bool,
    error: Option<&str>,
    on_fetch: impl Fn(&gpui::ClickEvent, &mut gpui::Window, &mut gpui::App) + 'static,
    cx: &mut gpui::App,
) -> gpui::Div {
    use crate::{icons, theme::*};
    use gpui::{SharedString, prelude::*};
    use gpui_component::{
        Disableable as _, h_flex,
        menu::{DropdownMenu, PopupMenuItem},
        v_flex,
    };

    let models = state.models().to_vec();
    let choices_current = state.active.as_ref().map(|ticket| ticket.cancelled.clone());
    let selected = input.read(cx).value().to_string();
    let field = input.clone();
    let status = match state.status() {
        Status::Idle => "可手动填写模型 ID，或点击右侧获取候选。".into(),
        Status::Loading => "正在获取候选模型，仍可手动填写。".into(),
        Status::Ready(models) if models.is_empty() => "服务未返回模型，可手动填写模型 ID。".into(),
        Status::Ready(models) => {
            format!("服务返回 {} 个候选，可展开选择或手动填写。", models.len())
        }
        Status::Failed(error) => error.message(),
    };
    let suffix = h_flex()
        .flex_shrink_0()
        .items_center()
        .gap_1()
        .child(
            input_action(SharedString::from(format!("{id}-fetch")))
                .icon(icons::refresh())
                .tooltip(if matches!(state.status(), Status::Ready(_)) {
                    "刷新模型列表"
                } else {
                    "获取模型列表"
                })
                .accessibility_label(if matches!(state.status(), Status::Ready(_)) {
                    "刷新模型列表"
                } else {
                    "获取模型列表"
                })
                .loading(state.loading())
                .disabled(disabled || state.loading())
                .on_click(on_fetch),
        )
        .when(!models.is_empty(), |row| {
            row.child(
                input_action(SharedString::from(format!("{id}-choose")))
                    .icon(icons::chevron_down())
                    .tooltip("选择模型")
                    .accessibility_label("从服务返回的候选中选择模型")
                    .disabled(disabled)
                    .dropdown_menu(move |menu, _, _| {
                        // 候选可能很多：弹层按共享约定限高并滚动（窗口半高，上限 450px）
                        models.iter().fold(menu.scrollable(true), |menu, model| {
                            let value = model.clone();
                            let field = field.clone();
                            let choices_current = choices_current.clone();
                            menu.item(
                                PopupMenuItem::new(model.clone())
                                    .checked(*model == selected)
                                    .on_click(move |_, window, cx| {
                                        // A primed (account-bound) list has no ticket; a
                                        // cancelled ticket disables an already-open menu.
                                        if choices_current.as_ref().is_some_and(|cancelled| {
                                            cancelled.load(Ordering::Acquire)
                                        }) {
                                            return;
                                        }
                                        field.update(cx, |input, cx| {
                                            input.set_value(value.clone(), window, cx)
                                        });
                                    }),
                            )
                        })
                    }),
            )
        });
    v_flex()
        .w_full()
        .min_w_0()
        .gap_2()
        .child(
            text_input(input)
                .w_full()
                .min_w_0()
                .disabled(disabled)
                .suffix(suffix)
                .aria_label(
                    error
                        .map(|error| format!("模型 ID，{error}"))
                        .unwrap_or_else(|| "模型 ID".into()),
                )
                .when(error.is_some(), |input| input.border_color(color(DANGER))),
        )
        .when_some(error, |view, error| {
            view.child(
                accessible_text(
                    SharedString::from(format!("{id}-field-error")),
                    error.to_owned(),
                )
                .w_full()
                .min_w_0()
                .whitespace_normal()
                .text_size(TEXT_AUX)
                .text_color(color(DANGER)),
            )
        })
        .child(
            // 非失败的常态说明走共享 ⓘ 辅助信息；失败仍用危险色错误文本（review4#2）
            if matches!(state.status(), Status::Failed(_)) {
                accessible_text(SharedString::from(format!("{id}-status")), status)
                    .w_full()
                    .min_w_0()
                    .whitespace_normal()
                    .text_size(TEXT_AUX)
                    .text_color(color(DANGER))
                    .into_any_element()
            } else {
                supporting_info(SharedString::from(format!("{id}-status")), status)
                    .text_size(TEXT_AUX)
                    .into_any_element()
            },
        )
}

#[cfg(test)]
mod tests {
    use super::{
        DISCOVERY_TIMEOUT, Error, Request, RequestKey, Response, State, Status, Transport,
        before_deadline, models_endpoint, parse_models, run_discovery,
    };
    use crate::credentials::{CredentialVault, MemoryCredentialVault, Secret};
    use crate::preferences::{Authentication, ServiceDraft, ServiceProtocol, ServicePurpose};
    use std::cell::Cell;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::time::{Duration, Instant};

    fn draft() -> ServiceDraft {
        let mut draft = ServiceDraft::new(ServicePurpose::Ai);
        draft.address = "https://example.test/gateway/v1".into();
        draft
    }

    fn run(
        request: Request,
        vault: &dyn CredentialVault,
        transport: &dyn Transport,
    ) -> Result<Vec<String>, Error> {
        run_discovery(
            request,
            vault,
            transport,
            Instant::now() + DISCOVERY_TIMEOUT,
            Instant::now,
        )
    }

    #[test]
    fn models_endpoint_preserves_the_configured_prefix_without_protocol_fallback() {
        for (address, protocol) in [
            ("https://example.test/gateway/v1/", ServiceProtocol::AiChat),
            (
                "https://example.test/gateway/v1/chat/completions",
                ServiceProtocol::AiChat,
            ),
            (
                "https://example.test/gateway/v1/audio/transcriptions",
                ServiceProtocol::SpeechTranscriptions,
            ),
        ] {
            assert_eq!(
                models_endpoint(address, protocol).unwrap(),
                "https://example.test/gateway/v1/models"
            );
        }
        for address in [
            "https://user:key@example.test/v1",
            "https://example.test/v1?key=secret",
            "https://example.test/v1#key",
            "file:///models",
            "https://example.test/v1/responses",
        ] {
            assert_eq!(
                models_endpoint(address, ServiceProtocol::AiChat),
                Err(Error::InvalidAddress)
            );
        }
    }

    #[test]
    fn response_accepts_only_bounded_model_ids_and_never_echoes_credentials() {
        let key = Secret::new("fixture-secret");
        let body = br#"{"data":[{"id":"z-model"},{"id":"a-model"},{"id":"a-model"},{"id":""},{"id":"debug-fixture-secret"},{"id":"bad\nmodel"}]}"#;
        assert_eq!(
            parse_models(body, Some(&key)).unwrap(),
            vec!["a-model", "z-model"]
        );
        assert!(parse_models(br#"{"data":[]}"#, None).unwrap().is_empty());
        for body in [
            br#"{"models":["model"]}"#.as_slice(),
            br#"{"data":[{}]}"#,
            br#"{"error":{"message":"fixture-secret"},"data":[]}"#,
        ] {
            let error = parse_models(body, Some(&key)).unwrap_err();
            assert_eq!(error, Error::InvalidResponse);
            assert!(!error.message().contains(key.expose()));
        }
    }

    #[test]
    fn stale_responses_cannot_survive_address_auth_key_or_editor_changes() {
        let draft = draft();
        let mut state = State::default();
        for change in 0..4 {
            let request = Request::from_draft(&draft, Secret::new("first-key")).unwrap();
            let ticket = state.begin(&request);
            let mut changed = draft.clone();
            let mut key = "first-key";
            match change {
                0 => changed.address = "https://other.test/v1".into(),
                1 => changed.authentication = Authentication::None,
                2 => key = "second-key",
                _ => state = State::default(),
            }
            let current = RequestKey::from_draft(&changed, key).unwrap();
            assert!(!state.complete(ticket, Some(&current), Ok(vec!["old-model".into()])));
            assert!(state.models().is_empty());
        }
        let first = Request::from_draft(&draft, Secret::new("first-key")).unwrap();
        let old = state.begin(&first);
        let second = Request::from_draft(&draft, Secret::new("first-key")).unwrap();
        let current = state.begin(&second);
        assert!(!state.complete(old, Some(second.key()), Ok(vec!["old-model".into()])));
        assert!(state.loading());
        assert!(state.complete(
            current,
            Some(second.key()),
            Ok(vec!["current-model".into()])
        ));
        assert_eq!(state.models(), &["current-model"]);
    }

    #[test]
    fn primed_catalog_behaves_like_a_ready_list_until_invalidated() {
        let mut state = State::default();
        state.prime(vec!["gpt-fixture".into()]);
        assert_eq!(state.models(), &["gpt-fixture"]);
        // 无连接票据：候选保持可选（菜单点击守卫只拒绝已取消的票据）
        assert!(state.active.is_none());
        state.begin_external();
        assert!(state.loading());
        assert!(state.models().is_empty());
        state.reject(Error::Custom("fixture failure".into()));
        assert!(matches!(state.status(), Status::Failed(Error::Custom(_))));
        assert_eq!(
            state.models().len(),
            0,
            "失败状态不提供候选，仍可手动填写"
        );
        state.prime(vec!["gpt-fixture".into()]);
        state.invalidate();
        assert!(state.models().is_empty());
        assert!(matches!(state.status(), Status::Idle));
    }

    struct FakeTransport {
        status: u16,
        calls: Cell<usize>,
        expected_key: Option<&'static str>,
    }
    impl Transport for FakeTransport {
        fn get(&self, endpoint: &str, authorization: Option<&Secret>) -> Result<Response, Error> {
            self.calls.set(self.calls.get() + 1);
            assert_eq!(endpoint, "https://example.test/gateway/v1/models");
            assert_eq!(authorization.map(Secret::expose), self.expected_key);
            Ok(Response {
                status: self.status,
                body: br#"{"data":[{"id":"candidate"}]}"#.to_vec(),
            })
        }
    }

    #[test]
    fn discovery_uses_unsaved_or_stored_credentials_without_staging_a_service() {
        let vault = MemoryCredentialVault::new();
        let mut draft = draft();
        let saved = vault.insert(Secret::new("saved-key")).unwrap();
        draft.credential = Some(saved);
        for (typed, expected) in [("", Some("saved-key")), ("typed-key", Some("typed-key"))] {
            let request = Request::from_draft(&draft, Secret::new(typed)).unwrap();
            let transport = FakeTransport {
                status: 200,
                calls: Cell::new(0),
                expected_key: expected,
            };
            assert_eq!(run(request, &vault, &transport).unwrap(), vec!["candidate"]);
            assert_eq!(transport.calls.get(), 1);
            assert!(
                draft.model.is_empty(),
                "discovery neither requires nor selects a model"
            );
        }
        draft.authentication = Authentication::None;
        let request = Request::from_draft(&draft, Secret::new("ignored-key")).unwrap();
        let transport = FakeTransport {
            status: 401,
            calls: Cell::new(0),
            expected_key: None,
        };
        assert_eq!(
            run(request, &vault, &transport),
            Err(Error::AuthenticationRefused)
        );
    }

    #[test]
    fn cancel_or_missing_credentials_do_not_send_and_empty_results_remain_distinct() {
        let vault = MemoryCredentialVault::new();
        let draft = draft();
        assert!(matches!(
            Request::from_draft(&draft, Secret::new("")),
            Err(Error::MissingKey)
        ));
        let request = Request::from_draft(&draft, Secret::new("key")).unwrap();
        let mut state = State::default();
        state.begin(&request);
        state.invalidate();
        let transport = FakeTransport {
            status: 200,
            calls: Cell::new(0),
            expected_key: Some("key"),
        };
        assert_eq!(run(request, &vault, &transport), Err(Error::Cancelled));
        assert_eq!(transport.calls.get(), 0);
        let request = Request::from_draft(&draft, Secret::new("key")).unwrap();
        let ticket = state.begin(&request);
        assert!(state.complete(ticket, Some(request.key()), Ok(vec![])));
        assert!(matches!(state.status(), Status::Ready(models) if models.is_empty()));
    }

    #[test]
    fn deadline_failure_is_visible_and_late_completion_cannot_replace_it_or_a_retry() {
        let draft = draft();
        let request = Request::from_draft(&draft, Secret::new("key")).unwrap();
        let current = request.key().clone();
        let mut state = State::default();
        let ticket = state.begin(&request);
        let (sender, receiver) = smol::channel::bounded(1);
        let result = smol::block_on(before_deadline(
            async { receiver.recv().await.unwrap() },
            Instant::now() + Duration::from_millis(5),
        ));
        assert_eq!(result, Err(Error::TimedOut));
        assert!(state.complete(ticket.clone(), Some(&current), result));
        assert!(matches!(state.status(), Status::Failed(Error::TimedOut)));
        assert!(!ticket.cancelled.load(Ordering::Acquire));

        // Model a blocking worker that finishes after its async receiver timed out.
        sender.try_send(Ok(vec!["late-model".into()])).unwrap();
        let late = receiver.try_recv().unwrap();
        assert!(!state.complete(ticket.clone(), Some(&current), late.clone()));
        assert!(matches!(state.status(), Status::Failed(Error::TimedOut)));

        let retry = Request::from_draft(&draft, Secret::new("key")).unwrap();
        let retry_ticket = state.begin(&retry);
        assert!(!state.complete(ticket, Some(&current), late));
        assert!(state.loading());
        assert!(state.complete(
            retry_ticket,
            Some(retry.key()),
            Ok(vec!["fresh-model".into()])
        ));
        assert_eq!(state.models(), &["fresh-model"]);

        // A ready worker must not win when the executor resumes after the deadline.
        assert_eq!(
            smol::block_on(before_deadline(
                async { Ok(vec!["already-late".into()]) },
                Instant::now(),
            )),
            Err(Error::TimedOut)
        );
    }

    struct ExpiringVault {
        resolved: AtomicBool,
    }

    impl CredentialVault for ExpiringVault {
        fn insert(&self, _secret: Secret) -> anyhow::Result<String> {
            panic!("discovery must not save credentials")
        }
        fn resolve(&self, _reference: &str) -> anyhow::Result<Secret> {
            self.resolved.store(true, Ordering::Release);
            Ok(Secret::new("saved-key"))
        }
        fn remove(&self, _reference: &str) -> anyhow::Result<()> {
            panic!("discovery must not remove credentials")
        }
    }

    #[test]
    fn credential_lookup_that_exhausts_the_deadline_never_sends_http() {
        let mut draft = draft();
        draft.credential = Some("saved-credential".into());
        let request = Request::from_draft(&draft, Secret::new("")).unwrap();
        let vault = ExpiringVault {
            resolved: AtomicBool::new(false),
        };
        let transport = FakeTransport {
            status: 200,
            calls: Cell::new(0),
            expected_key: Some("saved-key"),
        };
        let started = Instant::now();
        let deadline = started + DISCOVERY_TIMEOUT;
        // Advance a deterministic clock only when the credential call returns.
        // This exercises the blocking boundary without sleeping or using Keychain.
        let now = || {
            if vault.resolved.load(Ordering::Acquire) {
                deadline
            } else {
                started
            }
        };
        assert_eq!(
            run_discovery(request, &vault, &transport, deadline, now),
            Err(Error::TimedOut)
        );
        assert!(vault.resolved.load(Ordering::Acquire));
        assert_eq!(transport.calls.get(), 0);
    }

    #[test]
    fn response_arriving_after_deadline_cannot_be_accepted() {
        let request = Request::from_draft(&draft(), Secret::new("key")).unwrap();
        let vault = MemoryCredentialVault::new();
        let transport = FakeTransport {
            status: 200,
            calls: Cell::new(0),
            expected_key: Some("key"),
        };
        let started = Instant::now();
        let deadline = started + DISCOVERY_TIMEOUT;
        let now = || {
            if transport.calls.get() > 0 {
                deadline
            } else {
                started
            }
        };
        assert_eq!(
            run_discovery(request, &vault, &transport, deadline, now),
            Err(Error::TimedOut)
        );
        assert_eq!(transport.calls.get(), 1);
    }
}

#!/usr/bin/env python3
"""Capture the allowlisted official references, or verify their offline hashes.

M3 site prose has no verified redistribution licence: retain only the configured
short quotation. Full article text is saved only for the licensed sources in
sources.json. Network access is explicit through --refresh or --check-remote.
"""

from __future__ import annotations

import argparse
import concurrent.futures
import datetime as dt
import hashlib
from html.parser import HTMLParser
import json
from pathlib import Path
import re
import sys
import urllib.parse
import urllib.request


ROOT = Path(__file__).resolve().parents[1]
CATALOG = ROOT / "references/material/sources.json"
HOSTS = {"m3.material.io", "developer.android.com", "developers.google.com",
         "raw.githubusercontent.com", "www.apache.org", "creativecommons.org"}
VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link",
        "meta", "param", "source", "track", "wbr"}
SKIP_TAGS = {"script", "style", "devsite-key-takeaways-panel"}


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


class ArticleText(HTMLParser):
    """Extract actual Google DevSite article text, without navigation or scripts."""

    def __init__(self, url: str):
        super().__init__(convert_charrefs=True)
        self.url, self.depth, self.pre, self.skip = url, 0, 0, 0
        self.parts: list[str] = []
        self.links: list[str] = []
        self.found = False

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if not self.depth:
            if "devsite-article-body" not in a.get("class", "").split():
                return
            self.depth, self.found = 1, True
            return
        if tag not in VOID:
            self.depth += 1
        if tag in SKIP_TAGS:
            self.skip += 1
        if self.skip:
            return
        if re.fullmatch("h[1-6]", tag):
            self.parts.append("\n\n" + "#" * int(tag[1]) + " ")
        elif tag in {"p", "div", "ul", "ol", "section", "figure"}:
            self.parts.append("\n\n")
        elif tag == "li":
            self.parts.append("\n- ")
        elif tag == "br":
            self.parts.append("\n")
        elif tag == "tr":
            self.parts.append("\n| ")
        elif tag == "pre":
            self.pre += 1
            self.parts.append("\n\n```\n")
        elif tag == "a":
            self.links.append(urllib.parse.urljoin(self.url, a.get("href", "")))
            self.parts.append("[")
        elif tag == "img":
            label = a.get("alt", "Illustration") or "Illustration"
            src = urllib.parse.urljoin(self.url, a.get("src", ""))
            self.parts.append(f"\n[Visual omitted from text archive: {label}]({src})\n")

    def handle_endtag(self, tag):
        if not self.depth or tag in VOID:
            return
        if self.skip:
            if tag in SKIP_TAGS:
                self.skip -= 1
        elif tag == "a" and self.links:
            self.parts.append("](" + self.links.pop() + ")")
        elif tag in {"td", "th"}:
            self.parts.append(" | ")
        elif tag == "pre":
            self.pre -= 1
            self.parts.append("\n```\n\n")
        elif tag in {"p", "div", "section", "figure"} or re.fullmatch("h[1-6]", tag):
            self.parts.append("\n\n")
        self.depth -= 1

    def handle_data(self, data):
        if self.depth and not self.skip:
            if self.pre:
                self.parts.append(data)
            elif data.strip():
                self.parts.append(re.sub(r"\s+", " ", data))

    def text(self):
        if not self.found:
            raise ValueError("Actual DevSite article body was not found; refusing a shell page")
        lines, in_code = [], False
        for line in "".join(self.parts).splitlines():
            if line.strip() == "```":
                in_code = not in_code
            lines.append(line if in_code else line.strip())
        return re.sub(r"\n{3,}", "\n\n", "\n".join(lines)).strip()


class PlainText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts = []

    def handle_data(self, text):
        self.parts.append(text)


def fetch(url):
    if urllib.parse.urlparse(url).hostname not in HOSTS:
        raise ValueError(f"Unapproved reference host: {url}")
    with urllib.request.urlopen(url, timeout=45) as response:
        if urllib.parse.urlparse(response.url).hostname not in HOSTS:
            raise ValueError(f"Unapproved redirect: {response.url}")
        return response.read(), response.url


def capture(source):
    item = dict(source)
    try:
        raw, final_url = fetch(item.get("data_url", item["url"]))
    except OSError as error:
        raise ValueError(f"Cannot fetch {item['id']}: {error}") from error
    content = raw.decode("utf-8")
    kind = item["representation"]
    if kind == "html-short-excerpt":
        parser = ArticleText(final_url)
        parser.feed(content)
        normalized = " ".join(parser.text().split())
        quote = item["excerpt"]
        # Remove Markdown link syntax solely for exact text matching.
        normalized = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", normalized)
        if len(quote.split()) > 25 or quote not in normalized:
            raise ValueError(f"Missing or overlong quotation: {item['id']}")
        content = "> " + quote
        changes = "Short verbatim quotation of the official licensing statement. The complete policy page is linked above."
    elif kind == "m3-short-excerpt":
        page = json.loads(content)
        all_text = []
        for section in page["sections"]:
            if not section.get("isVisible", True):
                continue
            for block in section["contentBlocks"]:
                if block.get("isHidden"):
                    continue
                for chunk in block["contentChunks"]:
                    for key in ("htmlValue", "footer"):
                        if chunk.get(key):
                            parser = PlainText()
                            parser.feed(chunk[key])
                            all_text.extend(parser.parts)
        normalized = " ".join(" ".join(all_text).split())
        quote = item["excerpt"]
        if len(quote.split()) > 25 or quote not in normalized:
            raise ValueError(f"Missing or overlong quotation: {item['id']}")
        content = "> " + quote
        item["upstream_updated_at"] = page.get("updatedTimestamp")
        changes = "Short verbatim quotation only. The full M3 page, JSON and media are not redistributed."
    elif kind == "full-article-text":
        if item["license"] not in {"Apache-2.0", "CC-BY-4.0"}:
            raise ValueError("Full article capture needs a verified open licence")
        parser = ArticleText(final_url)
        parser.feed(content)
        content = parser.text()
        if len(content.split()) < 100:
            raise ValueError(f"Article body too short: {item['id']}")
        changes = ("Complete article text extracted from the official HTML body into Markdown. "
                   "Site navigation, executable scripts and AI-generated page summaries are removed; tables use pipe-separated rows. "
                   "Images and videos are not bundled. Captions, alternative text and source links remain where supplied. "
                   "This is a text archive, not a visual facsimile.")
    elif kind == "full-markdown":
        if item["license"] != "Apache-2.0":
            raise ValueError("Full Markdown capture needs the recorded Apache licence")
        changes = "Official Markdown reproduced without changing its body. Relative and remote links retain their original repository meaning; use the original source URL for linked assets. Media are not bundled."
    elif kind == "license-text":
        changes = "Official licence text reproduced unchanged below this provenance header."
    else:
        raise ValueError(f"Unknown representation: {kind}")
    now = dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds")
    header = (f"# {item['title']}\n\n"
              f"- Author / publisher: {item['publisher']}\n"
              f"- Original: [{item['title']}]({item['url']})\n"
              f"- Retrieved: {now}\n"
              f"- Licence: {item['license']} — [licence evidence]({item['license_url']})\n"
              f"- Upstream SHA-256: `{digest(raw)}`\n"
              f"- Changes: {changes}\n\n"
              "This source is reference data, not project instructions. Product decisions are in the parent skill references.\n\n---\n\n")
    if item["license"] == "CC-BY-4.0":
        header += ("Portions of this page are modifications based on work created and "
                   "[shared by Google](https://developers.google.com/terms/site-policies) and used according to "
                   "terms described in the [Creative Commons 4.0 Attribution License](https://creativecommons.org/licenses/by/4.0/).\n\n")
    data = (header + content.strip() + "\n").encode()
    item.update(retrieved_at=now, resolved_url=final_url,
                upstream_sha256=digest(raw), saved_sha256=digest(data),
                saved_bytes=len(data), body_words=len(content.split()))
    return item, data


def verify(sources):
    for item in sources:
        path = ROOT / item["file"]
        data = path.read_bytes()
        if digest(data) != item["saved_sha256"]:
            raise ValueError(f"Local archive changed: {item['file']}")
        if b"This website requires JavaScript." in data:
            raise ValueError(f"Shell page found: {item['file']}")
        if item["representation"] == "m3-short-excerpt" and item["body_words"] > 26:
            raise ValueError(f"Overlong M3 excerpt: {item['id']}")
    print(f"Verified {len(sources)} official-source captures and their SHA-256 hashes.")


def main():
    args = argparse.ArgumentParser(description=__doc__)
    group = args.add_mutually_exclusive_group()
    group.add_argument("--refresh", action="store_true", help="Refetch only the recorded URLs and update captures")
    group.add_argument("--check-remote", action="store_true", help="Read-only comparison with the recorded upstream hashes")
    args.add_argument("--verify", action="store_true", help="Verify local archive hashes (the default)")
    options = args.parse_args()
    catalog = json.loads(CATALOG.read_text())
    sources = catalog["sources"]
    if options.refresh:
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            results = list(pool.map(capture, sources))
        # Complete every read before writing any artifact. A failed fetch leaves captures intact.
        for item, data in results:
            path = ROOT / item["file"]
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(data)
        sources = [item for item, _ in results]
        catalog["sources"] = sources
        CATALOG.write_text(json.dumps(catalog, indent=2, ensure_ascii=False) + "\n")
    verify(sources)
    if options.check_remote:
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            blobs = list(pool.map(lambda x: fetch(x.get("data_url", x["url"]))[0], sources))
        changed = [s["id"] for s, blob in zip(sources, blobs) if digest(blob) != s["upstream_sha256"]]
        if changed:
            raise ValueError("Upstream responses changed: " + ", ".join(changed))
        print("All recorded upstream responses still match.")


if __name__ == "__main__":
    try:
        main()
    except (ValueError, OSError) as error:
        print(f"Reference validation failed: {error}", file=sys.stderr)
        sys.exit(1)
